  /* ── Australia (AU) ── */
  'te.au.dom.title': '国内出差——ATO 合理金额标准',
  'te.au.dom.desc': 'ATO 每年根据 TD 2025/4 公布\'合理金额\'。这些金额属于免除凭证要求的门槛——如雇主支付的金额未超过这些标准，且款项确实用于公务差旅，则无需保留每一张收据。\n\n主要规则：\n• 必须收到差旅津贴（而不仅是费用报销），并须显示在个人收入报表中\n• 必须实际将款项用于公务差旅\n• 连续 6 晚或以上的海外差旅：必须保留差旅记录（日记/行程单）\n• 住宿标准仅适用于商业住宿场所（酒店、汽车旅馆、服务式公寓）\n• 餐费：仅适用于按照用餐时间发生在差旅期间内的餐食\n• 杂费：按每天全额适用，不按不足一天的时段比例分摊\n\n薪资区间（薪资不包括所收到的津贴）：\n• 表 1：年薪不超过 $148,250\n• 表 2：年薪为 $148,251 至 $263,850\n• 表 3：年薪为 $263,851 或以上\n• 兼职员工：须将薪资折算为全职等值年薪\n\n加班餐费津贴：AUD 38.65（TD 2025/4，第 6 段）\n卡车司机餐费（所有目的地）：早餐 $31.15 | 午餐 $35.55 | 晚餐 $61.30',
