  'te.at.intl.title': '国际出差',
  'te.at.intl.desc': '国际出差适用由 WKO（奥地利经济商会）发布的按目的地划分的固定标准。\n\n适用三项标准：\n• 每日津贴（Tagessatz）：涵盖餐费及日常杂费\n• 住宿津贴（Nächtigungssatz）：涵盖住宿费用\n• 差额补贴（Differenzgebühren）：适用于部分高消费城市的额外补贴\n\n所有金额均以欧元（EUR）表示。Differential 一栏中的破折号（—）表示不适用额外补贴。',
  'te.at.intl.source': 'Austrian Federal Ministry – WKO Foreign Travel Allowance Rates',
