  /* ── Belgium (BE) ── */
  'te.be.dom.title': '国内出差',
  'te.be.dom.desc': '比利时为国内公务出差规定了政府统一的每日津贴标准，适用于所有雇主（公共部门及私营部门）。\n\n现行标准（自 2025 年 3 月 1 日起生效，每年指数化调整）：\n  • 每日津贴：每日 €21.22（仅涵盖餐费）\n  • 住宿津贴：每晚 €159.17（仅适用于雇主未支付住宿费用的情况）\n  • 月度定额津贴（适用于经常出差人员）：最高 16 × €21.22 = €339.52/月\n\n符合条件的出差必须满足以下要求：\n  • 确实与公务相关\n  • 出差时长至少为 6 小时\n  • 距离员工通常工作地点超过 25 公里\n  • 员工当天不得就同一餐费获得其他补偿\n\n如免费提供餐食，则须扣减相应金额：午餐扣减 35%，晚餐扣减 45%。餐券金额也必须扣除。同一笔费用不得同时凭收据报销并领取每日津贴。',
  'te.be.dom.source': 'FPS Finance — Domestic per diem (indexed); effective 1 March 2025',
  'te.be.dom.h.0': '类别',
  'te.be.dom.h.1': '标准（EUR）',
