	'te.bg.dom.r.5.0': '无收据的住宿',
	'te.bg.dom.r.5.1': '每晚最高 BGN 35 免税',
	'te.bg.dom.r.5.2': '法定',
	'te.bg.dom.r.6.0': '超过 200% 上限的金额',
	'te.bg.dom.r.6.1': '作为应税雇佣收入征税',
	'te.bg.dom.r.6.2': '法定',
	'te.bg.intl.title': '国际出差',
	'te.bg.intl.desc': '对于国际出差，保加利亚采用 Ordinance on Official Business Trips Abroad 附录 2 中规定的完整国家标准表。更新后的标准自 2025 年 2 月 1 日起生效（DV bр.8/2025）。\n\n适用以下三个组成部分：\n  • 每日津贴（дневни пари）：涵盖餐费和杂费——按国家制定，以 EUR 计\n  • 住宿津贴（квартирни пари）：每晚最高标准——按国家制定，以 EUR 计；也可凭收据按实际费用报销\n  • 交通费：凭收据另行报销\n\n税务处理：同样适用 200% 规则。附录 2 标准 200% 以内的金额可免税，超出部分属于应税收入。\n\n注意：完整的附录 2 国家清单涵盖 170 多个国家。以下仅列出部分主要标准——完整清单请参阅官方条例。',
	'te.bg.intl.source': 'Ordinance on Official Business Trips Abroad (NKSCS) — Appendix 2; last updated DV bр.8/2025 (eff. 1 Feb 2025)',
