	/* ── Canada (CA) ── */
	'te.ca.dom.title': '国内出差',
	'te.ca.dom.desc': '加拿大没有针对私营部门雇主的强制性法定每日津贴标准。加拿大税务局（CRA）为其自身员工设定津贴标准，而这些标准也被私营企业广泛用作参考。\n\n税务处理：如满足以下条件，差旅津贴对员工而言无需纳税：\n  1. 员工前往其通常所在市镇／大都市区域以外的地点出差\n  2. 津贴金额属于“合理”范围\n  3. CRA认为每餐最高CAD 23属于合理金额（简化方法）\n\nCRA发布的餐费标准（附录B——自2025年4月1日起生效）：\n  • 早餐：所有省份为$28.40；育空地区为$27.95；西北地区为$30.50；努纳武特地区为$30.55\n  • 午餐：所有省份为$27.40；育空地区为$25.65；西北地区为$37.00；努纳武特地区为$37.05\n  • 晚餐：所有省份为$57.70；育空地区为$73.95；西北地区为$79.20；努纳武特地区为$98.75\n  • 每日合计：所有省份为$113.50——每6个月审核一次\n  • 杂费津贴：每日$17.50\n  • 私人非商业住宿：每晚$50.00\n\n所有金额均以加元（CAD）计价，并已包含税费。',
	'te.ca.dom.source': 'CRA《差旅指令》——附录B（自2025年4月起生效，每半年审核一次）',
	'te.ca.dom.h.0': '餐食／类别',
	'te.ca.dom.h.1': '标准（CAD，含税）',
	'te.ca.dom.h.2': '地区／说明',
	'te.ca.dom.r.0.0': '早餐',
	'te.ca.dom.r.0.1': '$28.40',
