	'te.ca.intl.title': '国际出差',
	'te.ca.intl.desc': '对于国际出差，CRA根据《差旅指令》附录C发布按国家划分的餐费标准。该标准适用于联邦政府员工，也被私营企业广泛参考。\n\n主要规则：\n  • 杂费津贴：餐费津贴总额的32%（使用商业住宿时）\n  • 境外私人非商业住宿：每晚CAD $50\n  • 标准每季度更新（4月1日及10月1日）\n  • 如某地点未列出标准（*），则凭收据按实际发生且合理的费用报销\n\n以下列出附录C中部分标准（2025年10月），单位为每日CAD。所有标准仅涵盖餐费——住宿费用按实际发生金额另行报销。',
