  /* ── Chile (CL) ── */
  'te.cl.dom.title': '国内出差',
  'te.cl.dom.desc': '智利并未为私营部门雇主规定政府强制性的每日津贴标准。企业可自行制定标准。\n\n税务处理（Ley de Renta Art. 17 N°15）：支付给员工的每日津贴（viáticos）可免征所得税，但必须符合以下条件：\n  1. 用于真实的公务出差\n  2. 在 SII 认定下属于“合理”金额\n  3. 具备完整文件记录（差旅记录、出差目的、出差时长）\n\nSII（Servicio de Impuestos Internos）将根据个案评估金额是否合理，并未公布固定金额上限。实践中，SII 通常会参考公共部门标准（DFL 262/77）作为判断基准。\n\n根据 DFL 262/77 的公共部门标准（仅供参考——由于会定期调整，CLP 金额为约数）：\n  • 高级官员：CLP 60,000–80,000/天\n  • 普通员工：CLP 35,000–50,000/天\n\n注意：CLP 金额会随着通货膨胀而调整——实际适用前应始终通过 Contraloría General de la República 或 SII 查阅最新标准。',
  'te.cl.dom.source': 'Ley sobre Impuesto a la Renta Art. 17 N°15 — viáticos tax exemption rule',
  'te.cl.dom.h.0': '类别',
  'te.cl.dom.h.1': '标准（CLP/天，约数）',
  'te.cl.dom.h.2': '来源类型',
  'te.cl.dom.r.0.0': '公共部门——高级官员（DFL 262/77）',
  'te.cl.dom.r.0.1': 'CLP 60,000 – 80,000',
  'te.cl.dom.r.0.2': '政府参考标准',
  'te.cl.dom.r.1.0': '公共部门——普通员工',
  'te.cl.dom.r.1.1': 'CLP 35,000 – 50,000',
  'te.cl.dom.r.1.2': '政府参考标准',
  'te.cl.dom.r.2.0': '私营部门',
  'te.cl.dom.r.2.1': '依据公司政策（无法定标准）',
  'te.cl.dom.r.2.2': '市场惯例',
  'te.cl.dom.r.3.0': '免税待遇（Art. 17 N°15）',
  'te.cl.dom.r.3.1': '金额合理且具备文件记录即可免税——无固定上限',
  'te.cl.dom.r.3.2': '法定',
  'te.cl.dom.r.4.0': '超过 SII“合理”标准的部分',
  'te.cl.dom.r.4.1': '作为雇佣所得征税（Second Category Tax）',
  'te.cl.dom.r.4.2': '法定',
  'te.cl.intl.title': '国际出差',
  'te.cl.intl.desc': '对于国际出差，智利同样未为私营部门规定强制性每日津贴标准。公共部门依据 Decreto 1.121（更新 DFL 262/77）制定的美元标准，通常作为免税待遇的参考基准。\n\n税务处理：同样适用 Art. 17 N°15 的免税规定——国际 viáticos 在金额合理且具备文件记录的情况下可免税。SII 会参考公共部门的美元标准作为私营部门的参考基准。\n\n公共部门参考标准（Decreto 1.121，金额以 USD/天计）：\n  • 北美 / 西欧：USD 315/天\n  • 日本 / 澳大利亚 / 新西兰：USD 290/天\n  • 亚太地区（不含日本）：USD 270/天\n  • 拉丁美洲：USD 230/天\n  • 非洲 / 东欧 / 中东：USD 210/天\n\n这些标准对私营部门并无法律约束力——应作为合理性参考指引。',
  'te.cl.intl.source': 'DFL N° 262/77 — public sector per diem scales; SII rulings on reasonableness',
