	/* ── Croatia (HR) ── */
	'te.hr.dom.title': '国内出差',
	'te.hr.dom.desc': '克罗地亚根据《所得税法》（Zakon o porezu na dohodak）及《所得税条例》设定法定每日津贴（dnevnica）限额。该规定适用于所有雇主。\n\n国内每日津贴标准（2025年——克罗地亚自2023年1月1日起采用欧元）：\n  • 全额每日津贴（出差超过12小时）：最高每日EUR 30——免税\n  • 半额每日津贴（出差8至12小时）：最高每日EUR 15——免税\n  • 出差少于8小时：无权获得每日津贴\n\n主要规则：\n  • 每日津贴仅用于支付餐食及个人杂费\n  • 出发前必须签发有效的出差令（putni nalog）\n  • 如雇主提供免费餐食，每日津贴必须按以下标准扣减：\n    – 提供早餐：扣减每日标准的15%\n    – 提供午餐：扣减每日标准的35%\n    – 提供晚餐：扣减每日标准的35%\n    – 提供全膳（所有餐食）：扣减70%（员工保留30%）\n  • 同一天不得同时领取每日津贴（dnevnica）及野外工作津贴（terenski dodatak）\n  • 住宿：按实际发生并提供收据的费用报销（无固定标准）\n\n雇主可以支付超过EUR 30的金额——超过法定限额的部分将作为员工的应税收入。',
	'te.hr.dom.source': '克罗地亚税务管理局——《所得税条例》（Pravilnik o porezu na dohodak）',
	'te.hr.dom.h.0': '类别',
	'te.hr.dom.h.1': '标准（EUR／日）',
	'te.hr.dom.h.2': '来源类型',
	'te.hr.dom.r.0.0': '全额每日津贴——出差超过12小时',
	'te.hr.dom.r.0.1': '最高每日EUR 30（免税上限）',
	'te.hr.dom.r.0.2': '法定',
	'te.hr.dom.r.1.0': '半额每日津贴——出差8至12小时',
	'te.hr.dom.r.1.1': '最高每日EUR 15（免税上限）',
	'te.hr.dom.r.1.2': '法定',
	'te.hr.dom.r.2.0': '出差少于8小时',
	'te.hr.dom.r.2.1': '无权获得每日津贴',
	'te.hr.dom.r.2.2': '法定',
	'te.hr.dom.r.3.0': '提供早餐时的扣减',
