	'te.hr.dom.r.4.0': '提供午餐或晚餐时的扣减',
	'te.hr.dom.r.4.1': '每提供一餐，每日津贴减少35%',
	'te.hr.dom.r.4.2': '法定',
	'te.hr.dom.r.5.0': '提供所有餐食时的扣减',
	'te.hr.dom.r.5.1': '每日津贴减少70%（员工保留30%）',
	'te.hr.dom.r.5.2': '法定',
	'te.hr.dom.r.6.0': '超过EUR 30上限的部分',
	'te.hr.dom.r.6.1': '应税雇佣收入',
	'te.hr.dom.r.6.2': '法定',
	'te.hr.dom.r.7.0': '住宿',
	'te.hr.dom.r.7.1': '按实际发生并提供收据的费用报销——不适用固定标准',
	'te.hr.dom.r.7.2': '法定',
	'te.hr.intl.title': '国际出差',
	'te.hr.intl.desc': '对于国际出差，克罗地亚根据《境外商务差旅津贴政府法令》发布按国家划分的标准。更新后的标准刊登于《人民报》（Narodne novine，官方公报）。\n\n主要规则：\n  • 全额标准：境外出差超过12小时\n  • 半额标准（50%）：境外出差8至12小时\n  • 不支付津贴：少于8小时\n  • 津贴用于支付餐食及杂费；住宿费用另行凭收据报销\n  • 必须提供出差令（putni nalog），方可享受免税待遇\n  • 适用相同的餐食扣减规则（早餐15%，午餐／晚餐各35%）\n\n以下列出政府法令中部分国家的标准（EUR／日）。所有标准均以EUR计价。',
	'te.hr.intl.source': '《境外商务差旅津贴政府法令》——《人民报》（Narodne novine）',
	'te.hr.intl.h.0': '国家',
