	/* ── Czech Republic (CZ) ── */
	'te.cz.dom.title': '国内出差——Stravné（餐费津贴）',
	'te.cz.dom.desc': '捷克共和国根据《劳动法典》（Zákoník práce）第163条及第176条，通过年度法令设定法定每日津贴（stravné）标准。该标准适用于所有雇主。\n\n2025年国内出差标准（第475/2024号法令，自2025年1月1日起生效）：\n  • 出差5至12小时：每日CZK 148（私营部门最低标准）\n  • 出差12至18小时：每日CZK 225\n  • 出差超过18小时：每日CZK 353\n\n公共部门标准范围（第176条——每年在法定区间内设定）：\n  • 5至12小时：每日CZK 148–177\n  • 12至18小时：每日CZK 225–271\n  • 超过18小时：每日CZK 353–422\n\n税务处理：在法定最高限额以内支付的金额可完全免税（无需缴纳个人所得税，也无需缴纳社会保险及医疗保险费）。超过公共部门最高限额的部分将作为员工的应税工资收入。\n\n餐食扣减：如出差期间提供免费餐食，每日津贴将按以下比例扣减：\n  • 出差5至12小时：扣减70%\n  • 出差12至18小时：扣减35%\n  • 出差超过18小时：扣减25%\n\n住宿：按实际发生并提供收据的费用报销——不适用固定标准。',
	'te.cz.dom.source': '第475/2024号法令——2025年国内每日津贴；第262/2006号《劳动法典》',
	'te.cz.dom.h.0': '出差时长',
