	'te.cz.dom.r.8.2': '法定',
	'te.cz.intl.title': '国际出差——Zahraniční Stravné',
	'te.cz.intl.desc': '捷克共和国根据《劳动法典》第170条及财政部法令，每年发布按国家划分的国际每日津贴（zahraniční stravné）标准。\n\n2025年标准：第373/2024号法令（自2025年1月1日起生效）。\n各国家标准以EUR或USD计价，所有金额均为全天标准。\n\n按比例计算规则：\n  • 在境外超过18小时：100%（全额标准）\n  • 在境外12至18小时：全额标准的2/3\n  • 在境外1至12小时：全额标准的1/3\n  • 少于1小时：不支付津贴\n\n餐食扣减（提供免费餐食）：\n  • 按全额标准计算时，每顿免费餐食扣减25%\n  • 按2/3标准计算时扣减35%\n  • 按1/3标准计算时扣减70%\n\n私营部门：可以支付更高金额——超过财政部标准的部分将作为员工的应税收入。\n此外，可额外提供最高相当于每日津贴40%的零用钱补贴（kapesné），并可免税。',
	'te.cz.intl.source': '第373/2024号法令——2025年国际每日津贴标准（捷克共和国财政部）',
