	/* ── Denmark (DK) ── */
	'te.dk.dom.title': '国内出差',
	'te.dk.dom.desc': '丹麦由政府设定标准每日津贴（rejsegodtgørelse／diæter），并由丹麦税务局（SKAT）每年发布。该标准适用于所有支付免税津贴的雇主。\n\n2025年标准（由SKAT制定，自2025年1月1日起生效）：\n  • 餐食及杂费津贴（kostgodtgørelse）：每日DKK 597\n  • 住宿津贴（logigodtgørelse）：每晚最高DKK 256\n  • 25%零星开支津贴：每日DKK 149.25（即使已提供餐食仍可适用——用于支付咖啡、报纸及当地交通等费用）\n\n主要条件：\n  • 出差必须持续至少24小时，且员工必须在住所外过夜\n  • 工作地点必须属于临时工作地点——员工不得每日往返通勤\n  • 仅当雇主未支付住宿费用时，才可支付住宿津贴\n\n按比例计算：超过最初24小时后，津贴按每个已开始的小时计算。如出差持续40小时，可获得一个完整日标准，加上每日标准的16/24。\n\n餐食扣减（如雇主提供免费餐食）：\n  • 早餐：每日餐食标准的15%（DKK 89.55）\n  • 午餐：每日餐食标准的30%（DKK 179.10）\n  • 晚餐：每日餐食标准的30%（DKK 179.10）\n\n12个月规则：在同一临时工作地点工作的最初12个月内可适用标准津贴。超过12个月后，仅可报销有文件证明的实际费用。\n\n年度上限（员工税务扣除）：2025年为DKK 32,800——仅适用于员工自行申报的税务扣除；不会限制雇主支付免税津贴的能力。',
	'te.dk.dom.source': '丹麦税务局（SKAT）——2025年免税差旅津贴（rejsegodtgørelse／diæter）',
	'te.dk.dom.h.0': '津贴类型',
	'te.dk.dom.h.1': '标准（DKK——2025年）',
	'te.dk.dom.h.2': '来源类型',
	'te.dk.dom.r.0.0': '餐食及杂费津贴（kostgodtgørelse）——全天',
	'te.dk.dom.r.0.1': '每日DKK 597',
	'te.dk.dom.r.0.2': '法定',
	'te.dk.dom.r.1.0': '住宿津贴（logigodtgørelse）——每晚',
	'te.dk.dom.r.1.1': '每晚最高DKK 256',
	'te.dk.dom.r.1.2': '法定',
	'te.dk.dom.r.2.0': '25%零星开支津贴（即使提供免费餐食）',
	'te.dk.dom.r.2.1': '每日DKK 149.25',
	'te.dk.dom.r.2.2': '法定',
	'te.dk.dom.r.3.0': '餐食扣减——提供早餐',
	'te.dk.dom.r.3.1': 'DKK 89.55（餐食标准的15%）',
	'te.dk.dom.r.3.2': '法定',
	'te.dk.dom.r.4.0': '餐食扣减——提供午餐',
	'te.dk.dom.r.4.1': 'DKK 179.10（餐食标准的30%）',
	'te.dk.dom.r.4.2': '法定',
	'te.dk.dom.r.5.0': '餐食扣减——提供晚餐',
	'te.dk.dom.r.5.1': 'DKK 179.10（餐食标准的30%）',
	'te.dk.dom.r.5.2': '法定',
	'te.dk.dom.r.6.0': '免税津贴的最低出差时长',
	'te.dk.dom.r.6.1': '持续24小时，并在住所外过夜',
	'te.dk.dom.r.6.2': '法定',
	'te.dk.dom.r.7.0': '年度上限（仅限员工自行申报扣除）',
	'te.dk.dom.r.7.1': '每年DKK 32,800（2025年）——不会限制雇主支付的金额',
	'te.dk.dom.r.7.2': '法定',
	'te.dk.dom.r.8.0': '在同一临时工作地点超过12个月后',
	'te.dk.dom.r.8.1': '仅可报销有文件证明的实际费用（不再适用标准津贴）',
	'te.dk.dom.r.8.2': '法定',
	'te.dk.intl.title': '国际出差',
	'te.dk.intl.desc': '对于国际出差，丹麦采用相同的标准津贴制度。不过，境外出差的餐食津贴标准与国内标准相同（每日DKK 597）——没有单独按国家划分的国际津贴表。\n\n境外住宿：按实际发生并提供文件证明的费用报销，或由雇主采用每晚DKK 256的标准津贴。\n\n替代方式：许多丹麦公司采用美国国务院标准或公司自定的国际津贴标准，以更准确地覆盖实际成本——只要标准合理且有适当文件证明，SKAT均可接受。\n\n税务处理：适用相同规则。不超过SKAT标准的津贴可完全免税，超过标准的部分将作为应税收入。\n\n注意：对于每年国际出差超过180天的员工，可能适用特定的长期派驻规则——应咨询SKAT或税务顾问。',
	'te.dk.intl.source': '国际出差适用相同的SKAT规则——按实际报销或采用标准津贴',
	'te.dk.intl.h.0': '津贴类型／说明',
	'te.dk.intl.h.1': '标准（DKK——2025年）',
	'te.dk.intl.h.2': '来源类型',
	'te.dk.intl.r.0.0': '餐食及杂费津贴——国际出差',
	'te.dk.intl.r.0.1': '相同标准：每日DKK 597（无按国家划分的标准）',
	'te.dk.intl.r.0.2': '法定',
	'te.dk.intl.r.1.0': '住宿——国际出差',
