	/* ── Egypt (EG) ── */
	'te.eg.dom.title': '国内出差',
	'te.eg.dom.desc': '埃及没有针对私营部门雇主的政府强制性每日津贴标准。公司可自行制定差旅津贴政策。\n\n根据第91/2005号《所得税法》（经第7/2024号法律修订）的税务处理规定：\n  • 为真实商务出差而向员工支付的交通／差旅津贴（بدل الانتقال / بدل سفر），通常被视为非工资收入，不需缴纳个人所得税，前提是：\n    1. 用于真实且有文件证明的商务出差\n    2. 有有效收据或出差指令支持\n    3. 金额合理且不过高\n\n社会保险说明：如交通、差旅、餐食及住宿津贴不超过社会保险工资总额的30%，可不计入社会保险缴费工资基数。\n\n公共部门参考标准（部长令）：\n  • 埃及政府雇员的每日津贴由部长令规定，并根据员工职级、埃及境内目的地及出差时长而有所不同\n  • 根据职级及地点，标准通常为每日EGP 150–500\n  • 开罗及主要城市的标准通常高于其他省区\n\n注意：由于埃及通货膨胀率较高，EGP标准必须根据最新官方通告进行核实。所有标准均以埃及镑（EGP）计价。',
	'te.eg.dom.source': '埃及税务局（ETA）——关于差旅津贴及商务费用的第16条及第22条',
	'te.eg.dom.h.0': '类别',
	'te.eg.dom.h.1': '标准（EGP／日——参考）',
	'te.eg.dom.h.2': '来源类型',
	'te.eg.dom.r.0.0': '公共部门——高级官员（第1至第4级）',
	'te.eg.dom.r.0.1': '每日EGP 400–500（视职级及目的地而定）',
	'te.eg.dom.r.0.2': '政府参考标准',
	'te.eg.dom.r.1.0': '公共部门——中层官员',
	'te.eg.dom.r.1.1': '每日EGP 250–400',
	'te.eg.dom.r.1.2': '政府参考标准',
	'te.eg.dom.r.2.0': '公共部门——辅助人员',
	'te.eg.dom.r.2.1': '每日EGP 150–250',
	'te.eg.dom.r.2.2': '政府参考标准',
	'te.eg.dom.r.3.0': '私营部门',
	'te.eg.dom.r.3.1': '按公司政策执行——无法定标准',
	'te.eg.dom.r.3.2': '市场惯例',
	'te.eg.dom.r.4.0': '税务处理（第91/2005号《所得税法》）',
	'te.eg.dom.r.4.1': '如用于真实商务出差且有文件证明，则无需纳税',
	'te.eg.dom.r.4.2': '税务机关指引',
	'te.eg.dom.r.5.0': '社会保险豁免',
	'te.eg.dom.r.5.1': '最高可达工资总额的30%——不计入社会保险缴费基数',
	'te.eg.dom.r.5.2': '法定',
	'te.eg.dom.r.6.0': '被认定为不合理的金额',
	'te.eg.dom.r.6.1': '重新归类为工资——需缴纳个人所得税（累进税率最高27.5%）',
	'te.eg.dom.r.6.2': '法定',
	'te.eg.intl.title': '国际出差',
	'te.eg.intl.desc': '对于国际商务出差，埃及适用相同的《所得税法》框架——如属于真实商务出差且有文件证明，员工报销的实际差旅费用（住宿、餐食及交通）可免税。\n\n政府没有发布适用于私营部门国际每日津贴的标准表。许多埃及跨国公司及私营企业会参考美国国务院每日津贴标准或联合国国际公务员制度委员会（ICSC）标准。\n\n美国国务院针对埃及的参考标准（仅供参考）：\n  • 开罗：住宿每晚USD 175，加餐食及杂费每日USD 98\n  • 亚历山大及其他城市：标准较低（应查阅美国国务院发布的最新标准）\n\n电子发票说明：自2025年1月起，埃及要求可在税前扣除的商务费用提供电子收据。对于国际差旅费用，应尽可能确保取得合规的电子发票。',
	'te.eg.intl.source': '国际商务出差的差旅津贴适用相同的个人所得税免税框架',
	'te.eg.intl.h.0': '目的地',
	'te.eg.intl.h.1': '参考标准（USD／日）',
	'te.eg.intl.h.2': '来源类型',
