	/* ── Finland (FI) ── */
	'te.fi.dom.title': '国内出差',
	'te.fi.dom.desc': '芬兰由政府设定每日津贴最高标准，并由芬兰税务管理局（Vero）每年发布。该标准适用于所有雇主——在规定限额内支付的金额可完全免税。\n\n2025年国内出差标准（自2025年1月1日起生效）：\n  • 部分每日津贴（出差6至10小时）：每日€24\n  • 全额每日津贴（出差超过10小时）：每日€53\n  • 餐费津贴（未支付每日津贴，且需在正常工作地点以外用餐）：每日€13.25\n  • 夜间出行津贴（21:00至07:00期间至少出行4小时）：每日€16\n\n主要条件：\n  • 出差目的地必须距离雇主所在地或员工住所超过15公里\n  • 同时距离工作地点和住所均超过5公里\n  • 住宿：按实际发生并提供收据的费用报销（不设住宿固定津贴标准）\n\n餐食扣减规则（如雇主提供餐食）：\n  • 提供1顿免费餐食 = 部分每日津贴减少50%；对于全额每日津贴，提供1顿免费餐食不扣减，提供2顿免费餐食时减少50%\n\n雇主可以支付高于Vero最高标准的金额——超出部分将作为应税收入。未签署劳动合同的员工不符合免税每日津贴的资格。',
	'te.fi.dom.source': '芬兰税务管理局（Vero）——2025年免税津贴决定',
	'te.fi.dom.h.0': '津贴类型／出差时长',
	'te.fi.dom.h.1': '标准（欧元——2025年）',
	'te.fi.dom.h.2': '来源类型',
	'te.fi.dom.r.0.0': '部分每日津贴——出差6至10小时',
