	'te.fi.intl.title': '国际出差',
	'te.fi.intl.desc': '对于国际出差，芬兰每年发布按国家划分的每日津贴最高标准。适用标准取决于出差日结束时所在的国家（最后一晚住宿地点）。\n\n主要规则：\n  • 每个出差日持续至少24小时时，适用全额标准\n  • 如返程时间超过最后一个完整出差日2至10小时：额外一天适用半额标准\n  • 如返程时间超过10小时：额外一天适用全额标准\n  • 如提供2顿或以上免费餐食，每日津贴扣减50%\n  • 住宿：仅按实际发生并提供收据的费用报销——国际出差不设固定标准\n  • 夜间出行（境外且未发生住宿）：如符合条件，可支付€18固定津贴\n\n以下标准为Vero年度决定中规定的2025年标准。此处仅列出部分主要国家——完整的200多个国家和地区标准请参阅vero.fi。',
