	'te.fr.dom.title': '国内商务出差 — 长途出差（Grand Déplacement）',
	'te.fr.dom.desc': '法国由URSSAF公布适用于所有雇主的最高每日差旅津贴（indemnité de grand déplacement）标准。这些标准界定了免征社会保险缴费的上限。不超过该上限的金额同样免征所得税。\n\n长途出差（grand déplacement）须同时满足以下两个条件：\n  • 员工住所与工作地点之间的单程距离≥50公里\n  • 且公共交通单程无法在1小时30分钟内完成\n  → 员工无法每天返回住所\n\n2025年国内标准（URSSAF — 2025年9月4日法令）：\n  餐费：\n    • 长途出差（无法返回住所）：€21.10/餐（不论出差时长）\n    • 短途出差 — 在餐厅用餐：€21.10/餐\n    • 工作场所以外的简餐/用餐：€10.30\n    • 工作场所内用餐（轮班/夜班）：€7.40\n\n  住宿（前3个月）：\n    • 巴黎及近郊地区（92、93、94省）：€75.60/晚\n    • 法国本土其他地区：€56.10/晚\n  第3个月后：减少15%。第25个月后：减少30%。超过6年后：不再享受免税待遇。\n\n注意：雇主也可凭收据报销实际费用（frais réels）— 只要费用真实且有文件证明，则不设金额上限。',
	'te.fr.dom.source': 'URSSAF — 职业费用：2025年上限（2025年9月4日法令 + 社会保障官方公报）',
	'te.fr.dom.h.0': '津贴类别',
