	'te.fr.dom.r.8.2': '法定规定',
	'te.fr.intl.title': '国际商务出差',
	'te.fr.intl.desc': '针对国际商务出差，法国采用欧洲及外交部每月公布的公务员目的地国家标准。这些标准是私营部门享受免征社会保险缴费报销待遇的法定参考基准。\n\n包括两个组成部分：\n  • 餐费/杂费每日津贴：按国家而异（见表格）\n  • 住宿：凭收据按实际费用报销。如雇主未支付住宿费，则根据目的地国家标准适用固定住宿津贴（indemnité de logement）\n\n私营部门：法律并未强制要求采用这些标准，但采用官方标准可确保免征社会保险缴费及所得税。超过官方标准的金额须缴纳社会缴费。\n\n部分主要标准（EUR/天 — 根据外交部标准整理的2025年代表性数据）。完整现行表格：https://www.legifrance.gouv.fr（搜索arrêté indemnités mission étranger）',
	'te.fr.intl.source': '境外差旅标准：欧洲及外交部每月公布的公务员差旅标准',
