	/* ── Georgia (GE) ── */
	'te.ge.dom.title': '国内商务出差',
	'te.ge.dom.desc': '格鲁吉亚根据《格鲁吉亚税法》规定员工商务差旅津贴的法定免税上限。\n\n国内每日差旅津贴 — 免税上限：\n  • 格鲁吉亚境内为GEL 30/天\n  • 根据《格鲁吉亚税法》，这是可向员工免税支付的最高每日津贴金额\n  • 超过GEL 30/天的金额视为应税雇佣收入，适用20%的个人所得税\n\n其他组成部分（如属真实费用且有文件证明，也可免税）：\n  • 交通费：凭收据按实际费用报销\n  • 酒店/住宿费：凭收据按实际费用报销\n\n适用对象：\n  • 格鲁吉亚公司的员工，包括主要工作地点位于格鲁吉亚的本地及外籍员工\n  • GEL 30的上限适用于所有公共及私营部门雇主\n\n注意：GEL（格鲁吉亚拉里）为当地货币。发布时汇率约为USD 1 = GEL 2.70（请通过格鲁吉亚国家银行nbg.gov.ge核实当前汇率）。',
	'te.ge.dom.source': '《格鲁吉亚税法》— 员工商务差旅津贴规定',
	'te.ge.dom.h.0': '类别',
	'te.ge.dom.h.1': '标准',
	'te.ge.dom.h.2': '来源类型',
	'te.ge.dom.r.0.0': '每日津贴 — 格鲁吉亚境内',
	'te.ge.dom.r.0.1': 'GEL 30/天（最高免税上限）',
	'te.ge.dom.r.0.2': '法定规定',
	'te.ge.dom.r.1.0': '超过GEL 30/天的金额',
	'te.ge.dom.r.1.1': '应税雇佣收入 — 适用20%的个人所得税',
	'te.ge.dom.r.1.2': '法定规定',
	'te.ge.dom.r.2.0': '交通费',
	'te.ge.dom.r.2.1': '凭收据按实际费用报销 — 完全免税',
	'te.ge.dom.r.2.2': '法定规定',
	'te.ge.dom.r.3.0': '格鲁吉亚境内住宿',
	'te.ge.dom.r.3.1': '凭收据按实际费用报销 — 完全免税',
	'te.ge.dom.r.3.2': '法定规定',
	'te.ge.intl.title': '国际商务出差',
	'te.ge.intl.desc': '针对国际出差，《格鲁吉亚税法》规定，员工津贴可在按目的地国家确定的金额范围内免税。\n\n格鲁吉亚并未发布一份统一的国际标准表，具体标准根据目的地国家的生活成本确定。雇主通常参考以下其中一种标准：\n  1. 目的地国家的美国国务院或联合国国际公务员制度委员会标准\n  2. 公司内部国际差旅政策\n  3. KPMG / Deloitte目的地参考标准\n\n税务处理：有文件证明且金额合理的国际差旅费用报销（住宿、餐费、杂费）无需缴纳格鲁吉亚个人所得税。被认定为不合理或缺乏文件证明的金额，可能被重新分类为应税雇佣收入。\n\n格鲁吉亚个人所得税税率：雇佣收入统一适用20%。\n格鲁吉亚没有社会保险制度（养老金缴费根据2019年《累积养老金法》另行适用）。',
	'te.ge.intl.source': '国际标准按国家而异 — 雇主根据目的地确定合理金额',
	'te.ge.intl.h.0': '类别 / 目的地',
