	/* ── Germany (DE) ── */
	'te.de.dom.title': '国内商务出差 — 额外餐费津贴（Verpflegungsmehraufwand）',
	'te.de.dom.desc': '德国根据《所得税法》第9(4a)条规定法定每日差旅津贴（Verpflegungsmehraufwand）标准。该标准适用于所有雇主，在法定上限范围内可完全免税。\n\n2025年国内标准（自2020年以来未变）：\n  • 出差少于8小时：€0（无津贴）\n  • 出差8至24小时，或多日出差的抵达日/离开日：€14/天\n  • 完整一天（24小时）：€28/天\n  • 住宿固定津贴（无住宿收据时）：€20/晚\n\n主要规则：\n  • 同一天的多次出差可以合并计算 — 如合计达到或超过8小时，则适用€14\n  • 3个月规则（Dreimonatsfrist）：在同一临时工作地点，仅前3个连续月份可免税支付每日差旅津贴。中断4周后，3个月期限重新计算\n  • 如免费提供餐食，须扣减：早餐−20%，午餐−40%，晚餐−40%（以当日完整每日津贴标准为计算基础）\n  • 所有超过€150的发票必须注明雇主名称、地址及增值税金额\n  • 原始收据必须以纸质或电子方式在欧盟境内备份保存',
	'te.de.dom.source': '德国联邦财政部函件；《所得税法》第4条及第9条 — 2025年国内标准自2020年以来未变',
	'te.de.dom.h.0': '出差时长 / 类别',
	'te.de.dom.h.1': '标准（EUR — 2025年）',
