	'te.de.dom.r.8.0': '超过法定标准的金额',
	'te.de.dom.r.8.1': '雇主可支付更高金额 — 超出部分属于应税收入，并须缴纳社会缴费',
	'te.de.dom.r.8.2': '法定规定',
	'te.de.intl.title': '国际商务出差',
	'te.de.intl.desc': '针对国际出差，德国采用联邦财政部每年12月公布的下一年度目的地标准。\n\n每个目的地设有三个标准：\n  1. 完整日标准（离开24小时）\n  2. 抵达日/离开日标准（如当日离开8小时或以上，也适用该标准）\n  3. 住宿固定津贴\n\n主要规则（与国内相同）：\n  • 免费餐食适用相同的扣减规则（20%/40%/40%）\n  • 同样适用3个月规则\n  • 如国家未列入表格：默认适用卢森堡标准\n  • 对已列国家的海外领地：适用该国本土标准\n\n所有标准均以EUR计价。来源：德国联邦财政部2024年12月5日函件（2025年标准）。',
	'te.de.intl.source': '自2025年1月1日起境外差旅费用及差旅费用补偿的税务处理',
