	/* ── Greece (GR) ── */
	'te.gr.dom.title': '国内商务出差',
	'te.gr.dom.desc': '希腊根据《个人劳动法法典》第144条规定法定最低每日差旅津贴。与大多数欧盟国家不同，希腊的每日差旅津贴视为应税收入 — 计入员工工资，并按其适用的所得税档次纳税。\n\n最低每日差旅津贴（自2025年4月1日起，因最低工资上调而调整）：\n  • 每日差旅津贴 = 法定最低日工资，或法定最低月工资的1/25\n  • 法定最低日工资（自2025年4月1日起）：€39.30/天（蓝领员工）\n  • 最低月工资的1/25（自2025年4月1日起）：€880 ÷ 25 = €35.20/天\n\n重要更新：自2026年4月1日起，最低工资提高至€920/月。\n  • 新的1/25标准：€920 ÷ 25 = €36.80/天\n  • 新的最低日工资（蓝领员工）：€41.09/天\n\n主要规则：\n  • 员工离家过夜时，必须支付每日差旅津贴\n  • 不论目的地为何，标准相同 — 所有国内地点适用同一标准\n  • 每日差旅津贴按每个离家过夜晚数计算，而非按日历日计算\n  • 所有每日差旅津贴均作为雇佣收入纳税，适用9%–44%的累进个人所得税税率\n\n如雇主提供餐食或住宿，适用以下扣减：\n  • 同时提供餐食及住宿：每日差旅津贴减少3/4（仅支付1/4）\n  • 仅提供餐食：每日差旅津贴减少1/2\n  • 仅提供住宿：每日差旅津贴减少1/5\n\n差旅费用（机票、火车票及有收据的住宿费）如确实用于商务目的且有文件证明，可另行报销且无需缴纳所得税。',
	'te.gr.dom.source': '《个人劳动法法典》第144条 — 每日差旅津贴义务；希腊《所得税法》第4172/2013号法律',
	'te.gr.dom.h.0': '类别',
	'te.gr.dom.h.1': '标准 / 金额',
	'te.gr.dom.h.2': '来源类型',
	'te.gr.dom.r.0.0': '法定最低日工资（自2025年4月1日起）— 蓝领员工',
	'te.gr.dom.r.0.1': '€39.30/天',
	'te.gr.dom.r.0.2': '法定规定',
	'te.gr.dom.r.1.0': '最低月工资的1/25（自2025年4月1日起）— 白领员工',
	'te.gr.dom.r.1.1': '€35.20/天（€880 ÷ 25）',
	'te.gr.dom.r.1.2': '法定规定',
	'te.gr.dom.r.2.0': '法定最低日工资（自2026年4月1日起）',
	'te.gr.dom.r.2.1': '€41.09/天',
	'te.gr.dom.r.2.2': '法定规定',
	'te.gr.dom.r.3.0': '最低月工资的1/25（自2026年4月1日起）',
	'te.gr.dom.r.3.1': '€36.80/天（€920 ÷ 25）',
	'te.gr.dom.r.3.2': '法定规定',
	'te.gr.dom.r.4.0': '税务处理',
	'te.gr.dom.r.4.1': '全额应税 — 计入工资，并按员工适用的个人所得税档次纳税（9%–44%）',
	'te.gr.dom.r.4.2': '法定规定',
	'te.gr.dom.r.5.0': '雇主同时提供餐食及住宿',
