	'te.gr.intl.title': '国际商务出差',
	'te.gr.intl.desc': '国际出差适用相同框架。每日差旅津贴按法定最低日工资或最低月工资的1/25确定，与国内出差标准相同。希腊劳动法没有单独的国际标准表。\n\n国际出差的每日差旅津贴仍作为雇佣收入纳税。\n\n欧盟委员会参考标准（仅供参考 — 对希腊私营部门不具法律约束力）：\n  • 希腊（入境）：€82/天 + 住宿€140/晚（欧盟委员会2022年标准）\n  • 对于出境出差，欧盟委员会公布按国家划分的标准（参见ec.europa.eu）\n\n许多在希腊经营的跨国企业采用较高的国际每日差旅津贴标准，并参考欧盟委员会或美国国务院标准。这些标准本身可以采用，但全部每日差旅津贴仍须纳税。只有另行凭收据报销的实际费用（机票、酒店）可免税。',
	'te.gr.intl.source': 'PwC税务摘要 — 希腊个人所得确认；欧盟委员会境外差旅参考标准',
