	/* ── Hungary (HU) ── */
	'te.hu.dom.title': '国内商务出差',
	'te.hu.dom.desc': '匈牙利根据第437/2015号政府法令（XII.28.），为商务出差员工规定法定最低国内每日差旅津贴（napidíj）。\n\n国内每日差旅津贴：\n  • 最低标准：HUF 500/天（第437/2015号法令规定的法定最低标准）\n  • 例外：从事国内道路货运或客运的司机及货物随车人员：HUF 9,000/天（第96/2023号政府命令，自2023年3月30日起生效）\n\n国内每日差旅津贴的税务处理：\n  • HUF 500的法定固定每日津贴视为应税收入（按工资征税，适用15%的统一个人所得税税率及18.5%的社会保障缴费）\n  • 雇主也可选择凭发票报销实际餐费 — 此类报销按“特定已定义福利”征税：计税基础 = 金额 × 1.18，由雇主承担15%的个人所得税及13%的社会贡献税\n\n不符合每日差旅津贴条件的情况：\n  • 当日出差时间少于6小时\n  • 雇主在出差期间已为员工提供餐食\n\n住宿：凭收据按实际费用报销 — 与每日差旅津贴分开计算。',
	'te.hu.dom.source': '匈牙利国家税务和海关管理局（NAV）— 个人所得税及每日差旅津贴的税务处理',
	'te.hu.dom.h.0': '类别',
	'te.hu.dom.h.1': '标准 / 金额',
	'te.hu.dom.h.2': '来源类型',
	'te.hu.dom.r.0.0': '法定最低每日差旅津贴 — 普通员工',
	'te.hu.dom.r.0.1': 'HUF 500/天（按工资征税）',
	'te.hu.dom.r.0.2': '法定规定',
	'te.hu.dom.r.1.0': '每日差旅津贴 — 司机/货物随车人员（道路运输）',
	'te.hu.dom.r.1.1': 'HUF 9,000/天（第96/2023号政府命令，自2023年3月30日起）',
	'te.hu.dom.r.1.2': '法定规定',
	'te.hu.dom.r.2.0': '税务处理 — 固定每日津贴',
	'te.hu.dom.r.2.1': '应税：15%个人所得税 + 18.5%社会保障缴费（员工）',
	'te.hu.dom.r.2.2': '法定规定',
	'te.hu.dom.r.3.0': '替代方式：凭餐费发票报销',
	'te.hu.dom.r.3.1': '计税基础 = 金额 × 1.18 → 15%个人所得税 + 13%社会贡献税（雇主）',
	'te.hu.dom.r.3.2': '法定规定',
	'te.hu.dom.r.4.0': '当日出差少于6小时不支付每日差旅津贴',
	'te.hu.dom.r.4.1': '出差必须达到或超过6小时，且雇主未提供免费餐食',
	'te.hu.dom.r.4.2': '法定规定',
	'te.hu.dom.r.5.0': '住宿',
	'te.hu.dom.r.5.1': '凭收据按实际费用报销 — 单独报销',
	'te.hu.dom.r.5.2': '法定规定',
	'te.hu.intl.title': '国际商务出差',
	'te.hu.intl.desc': '针对国际商务出差，匈牙利并未公布按国家划分的每日差旅津贴标准表。津贴金额由雇主自行确定。\n\n关键税务规则（匈牙利《个人所得税法》— SZJA）：\n  • 境外出差每日餐费津贴仅有30%可免税\n  • 该30%的免税部分最高不得超过EUR 15/天\n  • 因此：每日餐费津贴的最高免税金额为EUR 15\n  • 超过该30%或EUR 15上限的金额，均属于员工应税收入\n\n示例：\n  • 雇主为前往德国出差支付EUR 50/天\n  • 免税部分：30% × EUR 50 = EUR 15（未超过EUR 15上限）\n  • 应税部分：EUR 50 − EUR 15 = EUR 35（按工资征税）\n\n其他单独报销项目：\n  • 住宿：凭收据按实际费用报销 — 不受EUR 15上限限制\n  • 交通（机票、火车票）：凭收据按实际费用全额报销\n  • 商务相关费用（出租车、停车费、电话费）：凭收据按实际费用报销\n\n时间规则：境外停留不足8小时不支付每日差旅津贴。如超过8小时，则可支付全额每日津贴。',
	'te.hu.intl.source': '境外每日餐费津贴仅30%免税，且最高为EUR 15/天（SZJA规定）',
	'te.hu.intl.h.0': '类别',
