	/* ── India (IN) ── */
	'te.in.dom.title': '国内商务出差 — 每日津贴',
	'te.in.dom.desc': '印度没有针对私营部门雇主的政府强制性每日差旅津贴标准。企业可自行设定标准。\n\n税务处理 — 商务出差每日津贴：\n根据《1961年所得税法》第10(14)(i)条及中央直接税委员会第2BB号规则：\n  • 员工因离开正常工作地点而产生的一般日常费用，如由雇主支付每日津贴用于承担该等费用，则该津贴可完全免征所得税\n  • 此项免税没有法定金额上限 — 只要确实用于商务出差，全部金额均可免税\n  • 新旧税制下均适用\n\n重要区别：\n  • 商务出差每日津贴（第10(14)(i)条）：完全免税，无上限\n  • 探亲旅行津贴 / LTA（第10(5)条）：仅适用于印度境内的个人休假旅行，每4年周期可申报2次（2022–2025周期），仅适用于旧税制\n  • LTA仅涵盖实际交通费用 — 不包括餐费、酒店或观光费用\n\n政府 / 公共部门：中央政府员工根据FR/SR（基本规则 / 补充规则）中的TA/DA规定执行。标准按职级划分：\n  • 职级工资≥INR 10,000：餐费INR 500/天 + 按城市等级确定酒店标准\n  • 职级工资INR 5,400–9,999：INR 300/天\n  • 职级工资INR 1,800–4,799：INR 240/天\n私营部门通常参考这些标准或采用市场标准。',
	'te.in.dom.source': '中央直接税委员会第2BB号规则 — 用于承担商务出差一般日常费用的每日津贴：完全免税且无上限',
	'te.in.dom.h.0': '类别',
	'te.in.dom.h.1': '标准 / 金额',
	'te.in.dom.h.2': '来源类型',
	'te.in.dom.r.0.0': '商务出差每日津贴 — 私营部门',
	'te.in.dom.r.0.1': '依据公司政策 — 无法定标准',
	'te.in.dom.r.0.2': '市场惯例',
	'te.in.dom.r.1.0': '税务豁免（《所得税法》第10(14)(i)条 + 第2BB号规则）',
	'te.in.dom.r.1.1': '完全免征印度所得税 — 无上限 — 新旧税制均适用',
	'te.in.dom.r.1.2': '法定规定',
	'te.in.dom.r.2.0': '探亲旅行津贴（LTA）— 第10(5)条',
	'te.in.dom.r.2.1': '每4年周期内2次旅行免税（2022–2025）；仅限印度境内；仅适用于旧税制',
	'te.in.dom.r.2.2': '法定规定',
	'te.in.dom.r.3.0': 'LTA涵盖范围',
	'te.in.dom.r.3.1': '仅限实际交通费用（交通票据）— 不包括餐费、酒店及观光',
	'te.in.dom.r.3.2': '法定规定',
	'te.in.dom.r.4.0': '政府 — 职级工资≥INR 10,000（高级官员）',
	'te.in.dom.r.4.1': '餐费INR 500/天；住宿按城市等级确定',
	'te.in.dom.r.4.2': '政府参考标准',
	'te.in.dom.r.5.0': '政府 — 职级工资INR 5,400–9,999',
	'te.in.dom.r.5.1': '餐费INR 300/天；住宿按城市等级确定',
	'te.in.dom.r.5.2': '政府参考标准',
	'te.in.dom.r.6.0': '政府 — 职级工资INR 1,800–4,799',
	'te.in.dom.r.6.1': '餐费INR 240/天；住宿按城市等级确定',
	'te.in.dom.r.6.2': '政府参考标准',
	'te.in.intl.title': '国际商务出差',
	'te.in.intl.desc': '针对国际出差，私营部门同样没有法定标准。如确实用于商务目的，商务差旅费用报销仍可根据第10(14)(i)条免税。\n\nFEMA及印度储备银行背景：印度居民的境外差旅支出受《外汇管理法》（FEMA）限额约束。在无需印度储备银行批准的情况下，银行可为每次商务出差提供最高USD 25,000的外汇，但须符合公司政策及用途证明要求。\n\n税务处理 — 国际每日差旅津贴：\n  • 作为境外公务出差每日津贴支付的金额，根据第10(14)(i)条可免税 — 无上限，但必须确实用于商务目的\n  • 超过实际费用或与商务目的无关的金额，须作为工资收入纳税\n\n政府参考标准（印度外交部官员境外出差）：\n  • A类城市（美国、英国、日本、澳大利亚、新加坡、瑞士、法国、德国）：USD 270–350/天（包括住宿部分）\n  • B类城市（东南亚、中东）：USD 180–250/天\n  • C类城市（南亚、非洲、东欧）：USD 120–180/天\n\n私营部门通常参考美国国务院或类似标准。',
	'te.in.intl.source': 'LTA仅涵盖印度境内个人休假旅行；国际旅行不适用LTA',
	'te.in.intl.h.0': '类别 / 目的地',
	'te.in.intl.h.1': '标准 / 备注',
	'te.in.intl.h.2': '来源类型',
