	/* ── Indonesia (ID) ── */
	'te.id.dom.title': '国内商务出差',
	'te.id.dom.desc': '印度尼西亚没有针对私营部门雇主的政府强制性每日差旅津贴标准。雇主可完全自行制定差旅津贴政策。\n\n根据印度尼西亚所得税法（PPh Pasal 21 / 第21条）的税务处理：\n  • 向员工支付的商务差旅费用报销通常无需缴纳所得税（PPh 21），前提是：\n    1. 报销款用于真实的商务差旅费用\n    2. 有有效收据或税务发票（faktur pajak）支持\n    3. 金额合理且并非变相工资\n\n  • 无收据证明的固定现金津贴（uang harian / uang saku）视为应税雇佣收入，须按5%–35%的累进个人所得税税率缴纳PPh 21\n\n政府 / 公共部门参考标准（财政部长条例 — PMK）：\n财政部每年为政府雇员制定每日差旅津贴标准。\n  • 每日津贴（Uang harian）：IDR 500,000–1,100,000/天（按职级划分）\n  • 住宿：IDR 500,000–2,200,000/晚（按城市等级及职级划分）\n  • 许多私营企业会参考这些标准\n\n所有金额均以印度尼西亚盾（IDR）计价。USD 1约等于IDR 15,800–16,000（2025年）。',
	'te.id.dom.source': 'PMK-81/2024（Coretax）+ 所得税法 — 商务差旅费用报销的税务处理',
