	'te.id.dom.r.7.0': '政府住宿标准 — 其他城市',
	'te.id.dom.r.7.1': 'IDR 500,000–1,200,000/晚',
	'te.id.dom.r.7.2': '政府参考标准',
	'te.id.intl.title': '国际商务出差',
	'te.id.intl.desc': '针对国际出差，印度尼西亚私营部门同样没有强制性每日差旅津贴标准。\n\n税务处理：\n  • 适用相同规则 — 凭收据按实际费用报销的国际差旅费用免税\n  • 无收据的固定现金津贴须缴纳PPh 21\n  • Coretax（PMK-81/2024，自2025年1月起生效）加强了文件要求\n\n政府国际差旅参考标准（财政部 — 部分标准）：\n  • 第一等级（美国、英国、日本、新加坡、澳大利亚）：USD 300–400/天\n  • 第二等级（欧洲、加拿大、韩国、阿联酋）：USD 220–320/天\n  • 第三等级（东南亚、中东、中国）：USD 160–250/天\n  • 第四等级（南亚、非洲、东欧）：USD 120–200/天\n\n注意：印度尼西亚政府的国际差旅标准以USD计价。\n私营部门通常参考财政部标准或美国国务院标准。',
	'te.id.intl.source': '适用相同的所得税框架；凭收据按实际费用报销免税',
