	/* ── Iraq (IQ) ── */
	'te.iq.dom.title': '国内商务出差',
	'te.iq.dom.desc': '伊拉克没有针对私营部门雇主公布政府强制性每日差旅津贴标准。企业可自行制定差旅津贴政策。\n\n根据经修订的《1982年第113号伊拉克所得税法》的税务处理：\n  • 在伊拉克为取得收入而发生且具有合法文件证明的商务费用，通常可由雇主税前扣除\n  • 对员工而言：风险津贴最高可按基本工资的30%免征所得税。真实商务出差的正常费用报销如符合以下条件，通常不视为员工应税收入：\n    1. 出差用于真实商务目的\n    2. 有文件证明（出差命令、收据）\n    3. 金额合理\n\n个人免税额（私营部门员工，2025年）：\n  • 单身人士：每年可扣除IQD 2,500,000\n  • 已婚人士：每年可扣除IQD 4,500,000\n\n伊拉克库尔德斯坦地区（KRI）：员工每月享有IQD 1,000,000的法定免税额。与伊拉克其他地区相比，KRI环境较稳定且更有利于商业活动，并适用单独的KRI投资法。\n\n注意：自2024年1月起，所有国内商业交易必须以伊拉克第纳尔（IQD）进行，包括国内商务差旅付款。\nIQD汇率：USD 1约等于IQD 1,310（官方汇率）。',
	'te.iq.dom.source': '伊拉克财政部 — 所得税法；商务差旅费用税前扣除规则',
	'te.iq.dom.h.0': '类别',
