	'te.iq.dom.r.5.0': '库尔德斯坦地区（KRI）— 每月免税额',
	'te.iq.dom.r.5.1': '每名员工IQD 1,000,000/月',
	'te.iq.dom.r.5.2': '法定规定',
	'te.iq.dom.r.6.0': '国内交易货币要求（自2024年1月起）',
	'te.iq.dom.r.6.1': '所有国内付款必须以IQD（伊拉克第纳尔）进行',
	'te.iq.dom.r.6.2': '法定规定',
	'te.iq.intl.title': '国际商务出差',
	'te.iq.intl.desc': '针对从伊拉克出发的国际商务出差，适用相同的一般原则 — 如确实用于商务目的，凭收据按实际费用报销的差旅费用可由雇主税前扣除，且员工免税。\n\n伊拉克政府未公布国际出差每日差旅津贴标准表。\n\n美国国务院针对前往伊拉克出差的参考标准（2025年）：\n  • 巴格达 — 美国政府驻地/军事设施：住宿USD 100 + 餐饮及杂费USD 54/天\n  • 巴格达 — 当地酒店：住宿USD 100 + 餐饮及杂费USD 54/天\n  • 伊拉克其他地区 — 美国政府驻地/军事设施：住宿USD 247 + 餐饮及杂费USD 82/天\n  • 伊拉克其他地区 — 当地酒店：住宿USD 247 + 餐饮及杂费USD 82/天\n\n上述为前往伊拉克的入境标准。对于伊拉克公民或受雇于伊拉克的员工出境出差，私营企业通常参考目的地国家的美国国务院或联合国国际公务员制度委员会标准。\n\n安全背景：由于伊拉克属于高风险环境，许多在当地经营的跨国企业采用较高的每日差旅津贴标准。石油行业企业在伊拉克较为常见，通常会根据安保成本及行动限制支付额外津贴。',
	'te.iq.intl.source': '美国国务院：巴格达住宿USD 100 + 餐饮及杂费USD 54；伊拉克其他地区住宿USD 247 + 餐饮及杂费USD 82',
