	/* ── Ireland (IE) ── */
	'te.ie.dom.title': '国内商务出差 — 公务员膳宿津贴',
	'te.ie.dom.desc': '爱尔兰税务局规定公务员膳宿津贴标准，该标准同时适用于公共及私营部门雇主，作为商务出差可享受免税待遇的最高金额。更新后的标准自2025年1月29日起生效（第04/2025号通函）。\n\n日间津贴（出差地点必须距离员工住所及通常工作地点均超过8公里）：\n  • 离开10小时或以上：€46.17/天\n  • 离开5至10小时：€19.25/天\n\n过夜津贴（出差地点必须距离住所及通常工作地点均至少100公里）：\n  • 正常标准（最多14晚）：€205.53/晚\n  • 折减标准（第15至28晚）：€184.98/晚\n  • 长期停留标准（第29至56晚）：€102.76/晚\n  • 超过56晚：须向税务局申请继续享受免税待遇\n\n凭证住宿方式（VA）— 仅适用于都柏林：\n  • 实际住宿费用（最高€205.53）加€46.17餐费\n\n主要规则：\n  • 只有员工次日工作5小时或以上时，日间津贴和过夜津贴方可同时申领\n  • 在任何单一地点领取膳宿津贴的总期限最长为6个月\n  • 也可报销实际费用，但不得超过公务员标准上限\n  • 超过公务员标准的金额视为应税雇佣收入，须缴纳PAYE、PRSI及USC',
	'te.ie.dom.source': 'Revenue.ie — 公务员膳宿津贴标准；自2025年1月29日起生效（第04/2025号通函）',
	'te.ie.dom.h.0': '津贴类型 / 时长',
