	'te.ie.dom.r.8.2': '税务机关指引',
	'te.ie.dom.r.9.0': '境外短期派遣 — 第2至3个月',
	'te.ie.dom.r.9.1': '国际标准的75%',
	'te.ie.dom.r.9.2': '税务机关指引',
	'te.ie.dom.r.10.0': '境外短期派遣 — 第4至6个月',
	'te.ie.dom.r.10.1': '国际标准的50%',
	'te.ie.dom.r.10.2': '税务机关指引',
	'te.ie.intl.title': '国际商务出差',
	'te.ie.intl.desc': '针对国际出差，爱尔兰采用第07/2017号通函规定的按国家划分标准。每个国家均设有过夜标准、VA（凭证住宿）标准及小时标准。\n\n境外短期派遣（最长6个月）：\n  • 第1个月：适用国际标准的100%\n  • 第2至3个月：适用标准的75%\n  • 第4至6个月：适用标准的50%\n\n长期派遣（超过6个月）：\n  • 第1个月：仅适用过夜标准（用于寻找住宿）\n  • 第1个月后：膳宿费用 + 10小时标准的一部分（须与税务局协商）\n\n部分国际过夜标准（来源：第07/2017号通函 — 以当地货币计价）：\n注意：这些过夜标准涵盖住宿及餐费。每个国家另设“10小时日间标准”和“5小时日间标准”。完整表格请参阅第07/2017号通函。',
