	/* ── Italy (IT) ── */
	'te.it.dom.title': '国内商务出差 — 出差津贴（Indennità di Trasferta）',
	'te.it.dom.desc': '意大利根据《统一所得税法》第51(5)条规定差旅津贴（indennità di trasferta）的法定免税上限。该标准适用于所有公共及私营部门雇主。\n\n存在三种报销制度（由雇主选择）：\n\n1. 固定津贴制度（sistema forfettario）— 津贴本身无需提供收据：\n   • 国内出差（离开员工居住市镇）：最高€46.48/天免税\n   • 超过€46.48/天：超出部分视为应税雇佣收入，须缴纳IRPEF及INPS\n\n2. 混合报销制度（sistema misto）— 固定津贴 + 部分凭收据报销费用：\n   • 如雇主同时支付餐费：固定津贴免税上限降至€30.99/天（减少1/3）\n   • 如雇主同时支付住宿费：同样降至€30.99/天\n   • 如餐费及住宿费均由雇主承担：降至€15.49/天（减少2/3）\n   • 凭收据报销的实际餐费及住宿费：完全免税，无上限\n\n3. 分析报销制度（sistema analitico — a piè di lista）— 所有费用均凭收据：\n   • 餐费、住宿费、差旅费、交通费：凭有效收据可完全免税\n   • 附带费用（洗衣费、电话费、小费）：每天最高€15.49免税\n\n重要事项 — 自2025年1月1日起适用的可追踪支付规则（《2025年预算案》，并经第15/E/2025号通函确认）：\n   • 国内出差：餐费、住宿费及出租车/NCC费用必须通过可追踪方式支付（银行卡、银行转账、数字支付），员工报销方可免税\n   • 以现金支付这些国内费用，可能导致相关报销变为应税收入。注意：公共交通费用（火车、飞机、巴士）不受此规则限制\n   • 境外出差：可追踪支付规则不适用 — 在国外仍可使用现金',
	'te.it.dom.source': '意大利税务局2025年12月22日第15/E号通函 — 可追踪支付及出差；《2025年预算案》',
