	'te.it.dom.r.2.2': '法定规定',
	'te.it.dom.r.3.0': '分析报销 — 凭收据报销实际餐费及住宿费',
	'te.it.dom.r.3.1': '完全免税 — 无上限',
	'te.it.dom.r.3.2': '法定规定',
