	'te.it.dom.r.5.2': '法定规定',
	'te.it.dom.r.6.0': '可追踪支付规则（自2025年1月1日起 — 仅限国内）',
	'te.it.dom.r.6.1': '餐费、住宿费及出租车/NCC必须通过银行卡或转账支付，方可免税',
	'te.it.dom.r.6.2': '法定规定',
	'te.it.dom.r.7.0': '金属机械行业集体协议（工业行业参考标准）',
	'te.it.dom.r.7.1': '完整出差€40/天',
	'te.it.dom.r.7.2': '集体协议',
	'te.it.dom.r.8.0': '专业事务所集体协议',
	'te.it.dom.r.8.1': '€15/天（8–24小时）或€30/天（超过24小时）',
	'te.it.dom.r.8.2': '集体协议',
	'te.it.intl.title': '国际商务出差',
	'te.it.intl.desc': '针对国际商务出差，适用相同的《统一所得税法》第51(5)条框架，但免税上限更高，以反映国际差旅成本。\n\n固定津贴制度（sistema forfettario）— 国际出差：\n  • 全额每日津贴（雇主不另行承担餐费/住宿费）：最高€77.47/天免税\n  • 如雇主另行支付餐费或住宿费：降至€51.65/天\n  • 如雇主同时支付餐费及住宿费：降至€25.82/天\n\n混合及分析报销制度与国内出差相同 — 凭收据报销的实际餐费、住宿费及交通费完全免税。附带费用：每天最高€25.82免税。\n\n可追踪支付规则：不适用于国际出差。员工在国外以现金支付费用，仍可在有文件证明的情况下享受免税报销。\n\n全国集体协议（CCNL）：许多行业设有各自的每日津贴标准。常见示例：\n  • 金属机械行业：完整日出差€40/天\n  • 商业/零售行业：最低标准 = 日工资比例的两倍\n  • 专业事务所：€15/天（8–24小时），€30/天（超过24小时）',
	'te.it.intl.source': '国际每日差旅津贴：固定津贴制度最高€77.47/天（津贴本身无需收据）',
