	/* ── Japan (JP) ── */
	'te.jp.dom.title': '国内商务出差',
	'te.jp.dom.desc': '日本没有针对私营部门雇主的政府强制性每日差旅津贴标准。各企业可自行设定标准，但相关机制及税务处理已有明确法律规定。\n\n根据《所得税法》第9(1)(iv)条及日本国税厅指引的税务处理：\n  • 根据公司正式制定的“差旅费用规程”（Ryohi Kisoku）向员工支付的每日差旅津贴可完全免税\n  • 在差旅费用规程范围内支付的金额，不征收所得税，也不征收居民税\n  • 如公司没有正式差旅费用规程，每日津贴可能被视为应税工资\n\n差旅费用规程要求：\n  • 公司必须正式制定并记录差旅费用规则\n  • 标准必须“合理”，不得人为提高以逃避税务\n  • 日本国税厅会在税务审计中质疑过高的每日津贴，尤其是住宿标准\n  • 个体经营者不能采用该制度 — 仅适用于公司法人\n\n常见市场参考标准（JPY — 视公司及员工职级而异）：\n  • 董事/高管：杂费JPY 3,000–8,000/天\n  • 经理级：JPY 2,000–5,000/天\n  • 普通员工：JPY 1,000–3,000/天\n  • 住宿：东京/大阪JPY 8,000–20,000/晚；其他城市JPY 5,000–12,000/晚\n\n注意：交通费（新干线、机票）及住宿费通常另行按实际费用报销，在差旅费用规程框架内同样免税。',
	'te.jp.dom.source': '日本国税厅（NTA）— 《所得税法》第9(1)(iv)条；差旅费用规程项下的商务差旅费用免税',
