	'te.jp.intl.title': '国际商务出差',
	'te.jp.intl.desc': '国际出差同样适用差旅费用规程框架。根据有效公司差旅制度支付的每日差旅津贴可完全免税。\n\n日本国税厅指引：金额应反映目的地的实际生活成本。过高的标准，例如普通出差支付JPY 50,000/天的杂费，可能在税务审计中受到质疑。\n\n常见私营部门国际参考标准（JPY/天 — 仅杂费；住宿及交通另行报销）：\n  • 北美 / 西欧：JPY 4,000–10,000/天\n  • 亚太地区：JPY 3,000–8,000/天\n  • 东南亚 / 南亚：JPY 2,000–5,000/天\n\n政府参考标准（财务省 — 政府雇员）：\n  • 每年在《国家公务员旅费规程》中公布\n  • 标准按目的地国家及员工职级而异\n  • 许多私营企业会参考这些标准\n\n政府国际住宿标准示例：\n  • 美国（A+职级）：JPY 35,000–50,000/晚\n  • 欧洲（法国、德国、英国）：JPY 30,000–45,000/晚\n  • 东南亚：JPY 15,000–30,000/晚',
	'te.jp.intl.source': '国际出差：适用相同框架 — 公司差旅费用规程范围内的金额完全免税',
