	/* ── Jordan (JO) ── */
	'te.jo.dom.title': '国内商务出差',
	'te.jo.dom.desc': '约旦没有专门针对私营部门员工的政府强制性每日差旅津贴标准。企业可自行设定标准。\n\n根据经2018年修订的《2014年第34号所得税法》的税务处理：\n  • 向员工支付的商务差旅津贴通常可由雇主作为合法商务费用税前扣除\n  • 对员工而言：用于真实商务出差的差旅津贴及费用报销，在金额合理且有适当文件证明的情况下，通常不计入应税雇佣收入\n  • 约旦所得税及销售税局会评估金额是否合理 — 明显高于实际差旅成本的金额可能被重新认定为应税工资收入\n\n约旦个人所得税背景：\n  • 个人所得税累进税率为5%至30%（年收入超过JOD 200,000的部分另征1%国家贡献税）\n  • 个人免税额：个人JOD 9,000/年 + 受扶养人JOD 9,000\n  • JOD与USD挂钩：1 JOD = USD 1.41（固定汇率）\n\n政府 / 公共部门参考标准：\n  • 约旦公务员根据职级及目的地领取每日差旅津贴\n  • 普通职级：国内JOD 25–50/天（餐费 + 杂费）\n  • 高级官员：国内JOD 50–80/天\n  • 私营部门通常参考这些政府标准',
	'te.jo.dom.source': '约旦所得税及销售税局（ISTD）— 第24条税务豁免及商务差旅规则',
