	'te.jo.intl.title': '国际商务出差',
	'te.jo.intl.desc': '针对从约旦出发的国际出差，适用相同的所得税法框架 — 合理的商务差旅费用报销对员工免税。\n\n美国国务院每日差旅津贴标准广泛用作约旦国际商务出差的参考基准（2025年标准）：\n  • 安曼（入境）：住宿USD 207/晚 + 餐饮及杂费USD 112/天\n\n约旦公共部门：公务员出境出差根据目的地国家及职级领取每日差旅津贴，其标准与区域内其他阿拉伯国家政府惯例相近。\n\n私营部门常见国际参考标准（USD/天 — 餐费 + 杂费）：\n  • 美国 / 西欧：USD 250–350/天\n  • 海湾国家（阿联酋、沙特阿拉伯、科威特）：USD 150–220/天\n  • 亚洲目的地：USD 150–250/天\n  • 区域内阿拉伯国家：USD 100–180/天\n\nJoFotara（约旦电子发票系统）：约旦自2023年起逐步推行电子发票制度，因此差旅费用文件证明的重要性日益提高。',
	'te.jo.intl.source': '美国国务院2025年标准：安曼住宿USD 207 + 餐饮及杂费USD 112/天（广泛用作私营部门参考标准）',
