	/* ── Kazakhstan (KZ) ── */
	'te.kz.dom.title': '国内商务出差 — 出差任务（Commandirovka）',
	'te.kz.dom.desc': '哈萨克斯坦以月度计算指数（MCI）的倍数为基础，规定员工商务出差（commandirovka）的法定免税每日差旅津贴（sutkovi / суточные）上限。\n\n税法框架（《2017年税法》第319条，并延续至自2026年1月1日起生效的新税法）：\n  • 国内每日差旅津贴（哈萨克斯坦境内）：每天最高6个MCI免税\n  • 2025年MCI = KZT 3,932\n  • 2025年每日免税上限：6 × 3,932 = KZT 23,592/天\n  • 请核实2026年MCI（通常在年度预算法律中确定）\n\n涵盖范围：\n  • 每日差旅津贴仅涵盖餐费及日常杂费\n  • 住宿费：凭收据按实际费用另行报销\n  • 交通费：凭相关文件按实际费用报销\n\n税务处理：\n  • 不超过6个MCI上限的金额：不征税，不计入个人收入\n  • 超过6个MCI/天的金额：视为应税雇佣收入，须缴纳个人所得税（2017年税法下统一税率10%；2026年新税法引入10%/15%的累进税率）及社会缴费\n\n重要事项 — 新税法（2025年7月18日签署，自2026年1月1日起生效）：\n  • 总统已签署新税法，引入累进个人所得税：年收入不超过8,500个MCI适用10%，超过部分适用15%。每日差旅津贴的MCI倍数可能通过配套法规进一步调整，应向当地税务顾问核实。',
	'te.kz.dom.source': '2025年月度计算指数（MCI）= KZT 3,932 | 国内每日差旅津贴免税上限：6个MCI = KZT 23,592/天',
