	'te.kz.intl.title': '国际商务出差',
	'te.kz.intl.desc': '针对国际商务出差，免税每日差旅津贴上限采用更高的MCI倍数，以反映较高的国际差旅成本。\n\n国际每日差旅津贴 — 免税上限：\n  • 哈萨克斯坦境外出差每天最高8个MCI\n  • 2025年：8 × KZT 3,932 = KZT 31,456/天（按KZT 500/USD计算，约USD 62/天）\n  • 住宿：凭收据按实际费用报销 — 雇主可全额税前扣除\n  • 交通（机票、火车票）：按实际费用报销 — 可全额扣除\n\n税务处理：\n  • 不超过8个MCI：不计入个人收入，不缴纳个人所得税及社会缴费\n  • 超过8个MCI/天：视为应税雇佣收入\n\n私营部门惯例：许多在哈萨克斯坦经营的跨国企业会根据目的地采用美国国务院或联合国国际公务员制度委员会标准，这些标准通常高于MCI上限。超过8个MCI的部分须纳税，但企业仍可支付并作为商务费用扣除。\n\n货币说明：KZT为记账本位币；USD广泛用于国际差旅预算。USD 1约等于KZT 500–510（2025年区间 — 请核实当前汇率）。',
	'te.kz.intl.source': '国际每日差旅津贴：每天8个MCI免税 = KZT 31,456/天（按2025年MCI计算）。2026年MCI公布后应重新核实。',
