	/* ── Kyrgyzstan (KG) ── */
	'te.kg.dom.title': '国内商务出差',
	'te.kg.dom.desc': '吉尔吉斯斯坦以月度参考指标（MRP / MRZ — Mesyachny Raschyotny Pokazatel）的倍数为基础，规定法定免税每日差旅津贴（sutkovi）上限。\n\n吉尔吉斯共和国税法（雇佣收入章节）：\n  • 国内每日差旅津贴：每天最高6个MRP免税\n  • 2025年MRP = KGS 100\n  • 2025年每日免税上限：6 × KGS 100 = KGS 600/天\n\n注意：吉尔吉斯斯坦的MRP设定为KGS 100，历史上相对稳定。应通过年度国家预算法律核实当前MRP数值。\n\n涵盖范围：\n  • 仅涵盖餐费及日常杂费\n  • 住宿：凭收据按实际费用报销\n  • 交通：凭相关文件按实际费用报销\n\n税务处理：\n  • 不超过6个MRP/天：不视为应税收入，免征个人所得税及社会缴费\n  • 超过6个MRP/天：视为应税雇佣收入，适用10%的统一个人所得税税率\n\n商务出差所需文件：\n  • 出差命令（雇主签发的trip order）\n  • 返回后提交费用报告\n  • 住宿及交通收据\n\nKGS汇率：USD 1约等于KGS 87–90（2025年 — 请通过吉尔吉斯斯坦国家银行核实）。',
	'te.kg.dom.source': '2025年月度参考指标（MRP）= KGS 100 | 国内每日差旅津贴免税上限：6个MRP = KGS 600/天',
