	'te.kg.dom.r.6.0': '所需文件',
	'te.kg.dom.r.6.1': '出差命令 + 费用报告 + 住宿/交通收据',
	'te.kg.dom.r.6.2': '法定规定',
	'te.kg.intl.title': '国际商务出差',
	'te.kg.intl.desc': '针对国际商务出差，吉尔吉斯斯坦的免税上限较高，以反映较高的国际差旅成本。\n\n国际每日差旅津贴 — 免税上限：\n  • 吉尔吉斯斯坦境外出差每天最高8个MRP\n  • 2025年：8 × KGS 100 = KGS 800/天（约USD 9/天）\n\n重要事项：以USD计算，该KGS上限非常低。实际操作中，大多数开展国际业务的雇主会支付远高于该标准的金额 — 超过8个MRP的部分视为应税雇佣收入，适用10%的统一个人所得税税率，但企业仍会支付并作为商务费用扣除。\n\n私营部门惯例：企业通常参考目的地国家的美国国务院或联合国国际公务员制度委员会标准，并将超过8个MRP的部分作为应税收入处理。\n\n其他凭收据免税报销项目：\n  • 国际航班及交通 — 按实际费用报销\n  • 境外酒店住宿 — 凭收据按实际费用报销\n  • 签证费、商务登记费用 — 按实际费用报销',
	'te.kg.intl.source': '国际出差：8个MRP/天 = KGS 800/天（按2025年MRP计算）。应通过年度预算法律核实当前MRP。',
