	/* ── Laos (LA) ── */
	'te.la.dom.title': '国内商务出差',
	'te.la.dom.desc': '老挝（老挝人民民主共和国）没有专门针对私营部门商务出差的政府强制性每日差旅津贴标准。企业可自行设定标准。\n\n根据老挝所得税法的税务处理：\n  • 工资及薪金收入，包括以现金或实物形式取得的津贴及其他福利，须按0%至25%的累进税率缴纳个人所得税\n  • 用于真实且有文件证明的商务差旅费用报销，通常不计入应税雇佣收入\n  • 无文件证明的固定现金津贴可能被视为应税收入\n\n劳动法背景：\n  • 自2023年10月1日起：最低工资 = LAK 1,600,000/月\n  • 自2024年10月1日起：对于月收入低于LAK 2,500,000的非专业员工，雇主须支付最高LAK 900,000的生活补贴（合计计算）\n\n政府 / 公共部门参考标准：\n  • 老挝公务员根据职级及出差时长领取每日差旅津贴\n  • 国内每日差旅津贴：通常为LAK 100,000–200,000/天（视职级而定）\n  • 私营部门通常参考这些政府标准\n\n货币说明：LAK已大幅贬值。USD 1约等于LAK 21,000–22,000（2025年）。',
	'te.la.dom.source': 'PWC老挝税务概览；劳动与社会福利部第3534/MLSW号通知（2024年10月）',
	'te.la.dom.h.0': '类别',
	'te.la.dom.h.1': '标准 / 金额',
