	'te.la.dom.r.1.0': '税务处理 — 有文件证明的差旅费用报销',
	'te.la.dom.r.1.1': '如属真实费用且有文件证明，通常免税',
	'te.la.dom.r.1.2': '税务机关指引',
	'te.la.dom.r.2.0': '税务处理 — 无文件证明的固定津贴',
	'te.la.dom.r.2.1': '可能须缴纳个人所得税（累进税率0%–25%）',
