	'te.la.dom.r.3.1': 'LAK 100,000–150,000/天（约USD 5–7）',
	'te.la.dom.r.3.2': '政府参考标准',
	'te.la.dom.r.4.0': '政府参考标准 — 高级官员',
	'te.la.dom.r.4.1': 'LAK 150,000–200,000/天',
	'te.la.dom.r.4.2': '政府参考标准',
	'te.la.dom.r.5.0': '最低工资（自2023年10月起）',
	'te.la.dom.r.5.1': 'LAK 1,600,000/月 — 不包括差旅津贴',
	'te.la.dom.r.5.2': '法定规定',
	'te.la.dom.r.6.0': '生活补贴（自2024年10月起）',
	'te.la.dom.r.6.1': '低收入非专业员工每月最高LAK 900,000',
	'te.la.dom.r.6.2': '法定规定',
	'te.la.intl.title': '国际商务出差',
	'te.la.intl.desc': '针对从老挝出发的国际商务出差，适用相同的所得税框架。合理且有文件证明的差旅费用报销通常免税。\n\n美国国务院每日差旅津贴标准是国际组织及在老挝经营的私营企业主要采用的参考基准：\n  • 万象（入境）：住宿USD 151/晚 + 餐饮及杂费USD 83/天（2025年）\n\n老挝政府官员出境出差的参考标准：\n  • 按目的地国家及职级划分\n  • 通常以USD计价\n  • 根据目的地及职级，标准为USD 80–300/天\n\n社会保障：雇主缴纳6%，员工缴纳5.5%的国家社会保障基金缴费。缴费以基本工资为基础，不包括合法差旅费用报销。\n\n实际操作说明：USD在老挝商务交易中被广泛使用。区域内出差预算通常以USD或泰铢（THB）制定。',
	'te.la.intl.source': '美国国务院2025年标准：万象住宿USD 151 + 餐饮及杂费USD 83/天（广泛用作私营部门参考标准）',
