	/* ── Lithuania (LT) ── */
	'te.lt.dom.title': '国内商务出差 — 每日差旅津贴（Dienpinigiai）',
	'te.lt.dom.desc': '立陶宛根据《劳动法典》及第98号政府法令（2017年）规定法定每日差旅津贴（dienpinigiai）标准。该标准适用于所有雇主。\n\n国内每日差旅津贴标准：\n  • EUR 28/天 — 在立陶宛境内商务出差可享受的最高免税每日津贴\n  • 根据《劳动法典》，立陶宛境内一日往返出差不支付每日差旅津贴\n\n税务处理：\n  • 不超过EUR 28/天的金额：完全免征个人所得税及Sodra社会保险缴费\n  • 超过EUR 28/天的金额：超出部分须缴纳个人所得税（自2026年起为20%/25%/32%累进税率）及Sodra社会保险缴费\n\n住宿及交通：\n  • 凭收据按实际费用报销\n  • 住宿没有统一固定标准 — 按有收据证明的实际费用报销\n\n2025年主要个人所得税税率（雇佣收入）：\n  • 年收入不超过EUR 126,532：20%\n  • 年收入超过EUR 126,532：32%\n  • 自2026年起：分为三个税率档次 — 20% / 25% / 32%（议会于2025年6月批准）\n\n2025年最低工资：EUR 1,038/月。Sodra最低缴费基数：EUR 1,038。\n2025年月平均工资（VDU）：EUR 2,108.88。',
	'te.lt.dom.source': '立陶宛《劳动法典》+ 第98号政府法令（2017年）— 国际出差标准',
	'te.lt.dom.h.0': '类别 / 时长',
	'te.lt.dom.h.1': '标准（EUR/天）',
	'te.lt.dom.h.2': '来源类型',
	'te.lt.dom.r.0.0': '立陶宛境内商务出差（过夜或多日）',
	'te.lt.dom.r.0.1': '€28/天（最高免税金额）',
	'te.lt.dom.r.0.2': '法定规定',
	'te.lt.dom.r.1.0': '立陶宛境内一日往返出差',
	'te.lt.dom.r.1.1': '不支付每日差旅津贴（《劳动法典》）',
	'te.lt.dom.r.1.2': '法定规定',
	'te.lt.dom.r.2.0': '不超过€28/天的金额',
