	'te.lt.dom.r.5.2': '法定规定',
	'te.lt.intl.title': '国际商务出差',
	'te.lt.intl.desc': '针对国际出差，立陶宛根据经更新的第98号政府决议（2017年）公布按国家划分的每日差旅津贴标准。这些标准是可享受免税待遇的最高每日津贴。\n\n政府决议中的部分标准 — EUR/天：\n（完整表格公布于lrs.lt，并由VMI汇总）\n\n规则：\n  • 在境外每个完整日或已开始的部分日均适用该标准\n  • 税务处理相同：不超过标准的金额免税；超过部分属于应税收入\n  • 住宿凭收据按实际费用报销\n  • 如没有针对某一国家的特定标准，则适用默认标准\n\n注意：立陶宛自2026年起实施重大个人所得税改革（议会于2025年6月通过国防融资方案）。每日差旅津贴规则本身保持不变，仅更新超出免税标准部分适用的边际税率。',
	'te.lt.intl.source': '第98号政府决议（2017年）— 国际商务出差按国家划分的每日差旅津贴表',
