	/* ── Luxembourg (LU) ── */
	'te.lu.dom.title': '国内商务出差',
	'te.lu.dom.desc': '卢森堡规定适用于所有雇主的法定每日差旅津贴上限（frais de séjour）。固定津贴在不超过公务员标准时免税；超过部分须缴纳所得税及社会保险缴费。\n\n允许采用两种报销方式：\n  1. 凭收据按实际费用报销（frais réels）— 无金额上限\n  2. 固定津贴（forfaitaire）— 以公务员标准为上限\n\n国内标准（自2025年1月1日起生效 — 2024年12月13日条例）：\n  • 日间津贴（餐费）：€14/天\n  • 夜间津贴（住宿费）：€56/晚\n\n夜间津贴说明：\n  • 如要使全额免税，必须提供酒店收据\n  • 如无收据：仅夜间标准的20%（€11.20）可免税\n\n距离卢森堡边境25公里以内的出差：\n  • 按国内出差处理（适用卢森堡标准）\n\n交通费用扣除（员工通勤扣除）：\n  • 与每日差旅津贴分开计算 — 适用于日常通勤费用\n  • 每月最高€214.50（年度上限€2,574）\n  • 按卢森堡直接税务局规定的距离公式（公里单位）计算',
	'te.lu.dom.source': '2024年12月13日政府委员会条例 — 标准自2025年1月1日起生效',
	'te.lu.dom.h.0': '类别',
	'te.lu.dom.h.1': '日间标准（EUR）',
	'te.lu.dom.h.2': '夜间标准（EUR）',
	'te.lu.dom.r.0.0': '卢森堡境内（日间津贴 / 夜间津贴）',
	'te.lu.dom.r.0.1': '€14/天',
	'te.lu.dom.r.0.2': '€56/晚（全额适用须提供收据）',
	'te.lu.dom.r.1.0': '住宿无收据',
	'te.lu.dom.r.1.1': '€14/天',
	'te.lu.dom.r.1.2': '€11.20/晚（€56的20%）',
	'te.lu.dom.r.2.0': '距离卢森堡边境25公里以内的出差',
	'te.lu.dom.r.2.1': '与国内标准相同：€14/天',
	'te.lu.dom.r.2.2': '€56/晚',
	'te.lu.dom.r.3.0': '超过公务员标准上限的金额',
	'te.lu.dom.r.3.1': '须纳税 — 须缴纳所得税及社会保险缴费',
	'te.lu.dom.r.3.2': '—',
	'te.lu.dom.r.4.0': '入境 — 海外雇佣员工前往卢森堡市中心出差',
	'te.lu.dom.r.4.1': '€60/天',
	'te.lu.dom.r.4.2': '€200/晚',
	'te.lu.dom.r.5.0': '入境 — 海外雇佣员工前往卢森堡基希贝格地区出差',
	'te.lu.dom.r.5.1': '€60/天',
	'te.lu.dom.r.5.2': '€240/晚',
	'te.lu.intl.title': '国际商务出差',
	'te.lu.intl.desc': '针对国际出差，卢森堡通过政府委员会条例每年更新按国家划分的标准。\n\n每个国家设有两个组成部分：\n  1. 日间津贴（餐费）：按每个完整日或已开始的部分日支付\n  2. 夜间津贴（住宿 + 早餐）：须提供收据；无收据时仅20%可免税\n\n欧盟轮值主席国加成：对于担任欧盟理事会轮值主席国的国家，在其任期内夜间标准提高10%。\n\n前往卢森堡的入境出差（员工受雇于海外）：\n  • 日间标准：€60/天；夜间标准：€200/晚（市中心）\n  • 夜间标准：€240/晚（基希贝格地区）\n\n所有标准均来源于BDO Luxembourg Memento 2025，并与2024年12月13日政府委员会条例核对确认。',
	'te.lu.intl.source': 'BDO Luxembourg Memento 2025差旅及住宿费用 — 完整国家表格（2025年2月7日）',
