	'te.my.dom.title': '国内商务出差',
	'te.my.dom.desc': '马来西亚没有针对私营部门雇主的政府强制性每日差旅津贴标准。企业可自行制定差旅津贴政策。\n\n根据《1967年所得税法》及马来西亚内陆税收局第5/2019号公共裁定的税务处理：\n\n1. 差旅津贴（Elaun Perjalanan）：\n   • 与商务差旅相关的津贴每年最高RM 6,000免税\n   • 适用于汽油津贴、过路费报销及履行工作职责产生的差旅费用\n   • 如雇主无法区分商务差旅和日常通勤：免税上限为RM 6,000\n   • 如实际费用超过RM 6,000，员工可进一步申报实际费用扣除\n\n2. 餐费津贴：\n   • 定期且统一发放的餐费津贴免税，但金额不得过高\n   • 加班、外埠或海外餐费津贴在符合以下条件时免税：\n     – 按雇主内部通告规定的固定标准支付\n     – 金额合理并以实际商务需要为基础\n\n3. 每日差旅津贴：\n   • 外埠出差每日津贴如符合LHDN指引则免税\n   • 必须以书面公司政策或内部通告中的固定标准为依据\n   • 被视为过高的金额可能被认定为应税雇佣收入\n\n政府 / 公共部门参考标准（JPA — 公共服务局）：\n  • TG48职级及以上：住宿RM 260–350/晚\n  • 普通员工：住宿RM 150–250/晚；餐费RM 30–60/天\n\n最低工资：RM 1,700/月（2025年）',
	'te.my.dom.source': '《1967年所得税法》— 福利及津贴；差旅津贴每年RM 6,000免税',
	'te.my.dom.h.0': '类别',
