	'te.my.dom.r.7.2': '法定规定',
	'te.my.intl.title': '国际商务出差',
	'te.my.intl.desc': '国际商务出差适用相同的LHDN框架。实际差旅费用报销通常免税。\n\n税务处理（LHDN第5/2019号公共裁定）：\n  • 外埠或海外出差的餐费及每日差旅津贴，如依据内部通告规定的固定标准支付，则可免税\n  • 每年RM 6,000的差旅津贴上限适用于国内商务差旅；海外津贴由于与实际费用相关，可能单独符合免税条件\n\n政府（JPA）国际参考标准：\n  • A组（美国、英国、日本、澳大利亚、新加坡、德国、法国、瑞士）：USD 200–350/天\n  • B组（中东、韩国、加拿大、新西兰）：USD 150–250/天\n  • C组（东盟、南亚）：USD 100–180/天\n  • D组（非洲、东欧）：USD 80–150/天\n\n新加坡税务局2025年针对马来西亚的可接受标准：SGD 73/天（供新加坡雇佣员工前往马来西亚出差时参考）。',
	'te.my.intl.source': '国际出差：每日差旅津贴适用相同框架；凭收据按实际费用报销免税',
