	/* ── Mauritius (MU) ── */
	'te.mu.dom.title': '国内商务出差',
	'te.mu.dom.desc': '毛里求斯没有针对私营部门雇主的政府强制性每日差旅津贴标准。企业可自行制定商务差旅政策。\n\n根据《1995年所得税法》及毛里求斯税务局指引的税务处理：\n\n1. 交通 / 差旅津贴（与通勤相关）：\n   • 以下两者中较低者免税：\n     – 实际支付的汽油或差旅津贴；或\n     – 每月基本工资的25%，每月最高MUR 20,000\n   • 适用于员工因公使用私家车\n   • 住所与工作地点之间通勤：往返巴士费用完全免税\n\n2. 商务出差费用报销（外埠 / 履行工作职责的差旅）：\n   • 真实商务出差产生的实际差旅费用报销，包括住宿、餐费及交通费，在符合以下条件时通常不视为应税收入：\n     – 有有效收据支持\n     – 用于真实商务目的\n     – 金额不过高\n\n2025/2026年所得税税率：\n  • 年收入首MUR 500,000：0%\n  • 接下来MUR 500,000：10%\n  • 剩余部分：20%\n  • 免税个人门槛：MUR 38,462/月\n  • 公平份额缴费（FSC）：对年应税收入超过MUR 12M的部分征收15%（2025年7月1日至2028年6月30日期间适用）\n\nMUR汇率：USD 1约等于MUR 45–47（2025年 — 请通过毛里求斯央行核实）。',
	'te.mu.dom.source': '毛里求斯税务局（MRA）— 《1995年所得税法》中的免税收入规定',
	'te.mu.dom.h.0': '类别',
