	'te.mu.dom.r.5.0': '公平份额缴费（FSC）',
	'te.mu.dom.r.5.1': '年应税收入超过MUR 12M的部分征收15%（2025年7月至2028年6月）',
	'te.mu.dom.r.5.2': '法定规定',
	'te.mu.dom.r.6.0': '私营部门 — 无法定每日差旅津贴标准',
	'te.mu.dom.r.6.1': '依据公司政策 — MRA评估金额是否合理',
	'te.mu.dom.r.6.2': '市场惯例',
	'te.mu.intl.title': '国际商务出差',
	'te.mu.intl.desc': '国际商务出差适用相同的MRA框架 — 真实且凭收据报销的差旅费用通常免税。\n\n政府没有公布适用于私营部门国际每日差旅津贴的标准表。\n\n美国国务院每日津贴标准（2025年 — 前往毛里求斯）：\n  • 路易港：住宿USD 193/晚 + 餐饮及杂费USD 98/天\n\n毛里求斯雇佣员工出境出差的常见私营部门参考标准：\n  • 欧洲 / 北美 / 澳大利亚：USD 200–350/天\n  • 中东 / 海湾国家：USD 150–250/天\n  • 非洲 / 亚太地区：USD 100–200/天\n  • 非洲区域内（肯尼亚、南非等）：USD 100–180/天\n\n新加坡税务局2025年针对毛里求斯的可接受标准：SGD 90/天（供新加坡雇佣员工前往毛里求斯出差时参考）。',
	'te.mu.intl.source': '美国国务院2025年标准：毛里求斯路易港住宿USD 193 + 餐饮及杂费USD 98/天 — 广泛用作私营部门参考标准',
