	/* ── Mexico (MX) ── */
	'te.mx.dom.title': '国内商务出差 — 差旅费（Viaticos）',
	'te.mx.dom.desc': '墨西哥税务管理局（SAT）规定商务差旅费用（viaticos）的最高税前扣除限额。这些并非法定每日差旅津贴标准，而是使相关费用可由雇主税前扣除并使员工免税的上限。\n\nSAT框架（《所得税法》第28条第V款及第93条第XVII款）：\n\n国内差旅费在符合以下条件时对员工免税：\n  1. 出差地点不在员工通常工作或居住的市镇范围内\n  2. 有第三方开具的CFDI数字税务收据，证明住宿或交通费用\n  3. 如只有餐费凭证而没有住宿或交通凭证：必须使用公司信用卡支付\n\nSAT国内最高税前扣除 / 免税上限：\n  • 餐费：MXN 750/天（国内）\n  • 汽车租赁：MXN 850/天\n\n80%银行卡支付规则：\n  • 至少80%的差旅费总额必须通过公司信用卡、借记卡或服务卡支付，雇主方可税前扣除\n  • 最多20%可使用现金支付（用于小额费用，年度最高MXN 15,000）\n\n超过SAT上限的金额：\n  • 视为员工应税收入，须缴纳1.92%–35%的个人所得税\n\n2026年UMA：MXN 117.31/天 | 最低工资：MXN 278.80/天（一般地区）。',
	'te.mx.dom.source': 'SAT：国内餐费上限MXN 750/天；汽车租赁MXN 850/天；须有第三方CFDI收据支持',
	'te.mx.dom.h.0': '类别',
	'te.mx.dom.h.1': 'SAT上限（MXN/天）',
