	'te.mx.dom.r.2.2': '税务机关指引',
	'te.mx.dom.r.3.0': '80%公司卡支付规则',
	'te.mx.dom.r.3.1': '差旅费总额至少80%须通过公司卡支付，雇主方可税前扣除',
	'te.mx.dom.r.3.2': '法定规定',
	'te.mx.dom.r.4.0': '现金差旅费（最高20%）',
	'te.mx.dom.r.4.1': '现金支付年度最高MXN 15,000（不使用银行卡）— 雇主可税前扣除',
	'te.mx.dom.r.4.2': '法定规定',
	'te.mx.dom.r.5.0': '超过SAT上限的金额',
	'te.mx.dom.r.5.1': '视为员工应缴ISR的收入（累进税率1.92%–35%）',
