	'te.mx.dom.r.6.0': '文件要求',
	'te.mx.dom.r.6.1': '须有第三方开具的CFDI，证明住宿或交通费用，方可享受免税待遇',
	'te.mx.dom.r.6.2': '法定规定',
	'te.mx.intl.title': '国际商务出差',
	'te.mx.intl.desc': '国际差旅费适用相同的SAT框架，但相关上限更高。\n\n国际差旅费 — SAT上限：\n  • 餐费：MXN 1,500/天（国际）\n  • 住宿：MXN 3,850/天（国际）\n  • 汽车租赁：MXN 850/天（与国内相同）\n\n适用相同条件：\n  • 必须有CFDI或同等效力的境外收据，证明住宿或交通费用\n  • 至少80%必须通过公司卡支付，雇主方可税前扣除\n  • 出差地点必须不在通常工作或居住的市镇范围内\n\n税务处理：\n  • 不超过SAT上限且文件完整：员工免税\n  • 超过上限的金额：视为员工应缴ISR的收入\n\n注意：国内餐费MXN 750/天及国际餐费MXN 1,500/天的标准多年来基本未变。每年应核查SAT《税务综合决议》（RMF），确认相关金额是否有更新。',
	'te.mx.intl.source': '差旅费至少80%须通过公司卡支付，方可作为雇主可税前扣除费用（SAT规则）',
