	/* ── Middle East (ME) ── */
	'te.me.dom.title': '海湾合作委员会及中东地区 — 各国国内每日差旅津贴',
	'te.me.dom.desc': '本表为海湾合作委员会（GCC）及更广泛中东国家提供区域参考。阿联酋、沙特阿拉伯、伊拉克和约旦均设有单独的详细表格。本表涵盖其余主要市场：科威特、巴林、阿曼、卡塔尔、黎巴嫩及埃及（摘要）。\n\n区域核心原则：所有海湾合作委员会国家（阿联酋、沙特阿拉伯、科威特、巴林、阿曼、卡塔尔）均不对雇佣收入征收个人所得税。海湾合作委员会国家对私营部门员工没有强制性每日差旅津贴要求。雇主可自行设定标准。\n\n海湾合作委员会国家的税务处理：\n  • 阿联酋、沙特阿拉伯、科威特、巴林、阿曼及卡塔尔均不对个人工资或薪金征收所得税\n  • 每日差旅津贴、其他津贴及福利通常对员工免税\n  • 企业所得税规则各不相同：阿联酋自2023年6月起征收9%的企业所得税；沙特阿拉伯征收20%的企业所得税；其他海湾合作委员会国家的规定各异\n\n非海湾合作委员会国家：约旦和黎巴嫩征收所得税 — 约旦请参阅约旦表格；黎巴嫩具有重要的经济背景因素，包括货币危机及USD/LBP双重汇率。',
	'te.me.dom.source': '本矩阵中另设阿联酋、沙特阿拉伯、伊拉克及约旦的单独国家表格（请参阅相应标签页）',
