	'te.me.intl.title': '美国国务院入境每日津贴标准（USD，2025年）',
	'te.me.intl.desc': '美国国务院针对前往中东目的地出差公布的2025年每日津贴标准。这些是美国政府出差人员采用的最高每日标准，也被广泛用作私营部门参考基准。\n\n标准 = 住宿费（每晚）+ 餐饮及杂费（每日），以USD计价。\n\n注意：海湾合作委员会国家主要商务城市的住宿成本通常较高。同一国家不同城市之间的标准可能存在显著差异。',
	'te.me.intl.source': '所列标准为美国国务院针对前往相关国家出差的每日津贴标准（以USD计价的住宿费 + 餐饮及杂费）',
