	/* ── Morocco (MA) ── */
	'te.ma.dom.title': '国内商务出差 — 差旅津贴（Indemnités de Déplacement）',
	'te.ma.dom.desc': '摩洛哥税务总局（DGI）根据《税法总则》（CGI）第57条，对免税津贴作出指引。私营部门雇主没有政府规定的固定强制性每日差旅津贴标准 — 企业可自行设定标准。\n\nCGI规定的免税津贴类别：\n\n1. 差旅津贴（Indemnité de déplacement）：\n   • 用于支付执行公务期间的住宿费及餐费\n   • 必须有有效发票或收据（pièces probantes）证明，或符合DGI公布的标准表（barèmes）\n   • 如无适当证明：视为应税雇佣收入\n\n2. 餐费津贴（Indemnité de panier）：\n   • 每个实际工作日最高MAD 30/天免税\n   • 在摩洛哥企业中非常常见\n\n3. 业务招待津贴（Indemnité de représentation）：\n   • 适用于发生业务招待费用的高级员工或管理人员\n   • 最高可按基本工资的10%免税\n\n4. 交通津贴（Indemnité de transport，通勤）：\n   • 城市范围内：最高MAD 500/月免税\n   • 城市范围外：最高MAD 750/月免税\n\n5. 巡访津贴（Prime de tournée，适用于外勤员工）：\n   • 对每日进行多次拜访的员工，最高MAD 1,500/月免税\n\n2025年所得税税率：年度累进税率0%–37%\n  • 年收入不超过MAD 40,000：0%\n  • MAD 40,001–60,000：10%\n  • MAD 60,001–80,000：20%\n  • MAD 80,001–100,000：30%\n  • MAD 100,001–180,000：34%\n  • 超过MAD 180,000：37%',
	'te.ma.dom.source': '《税法总则》（CGI）— 差旅津贴、餐费津贴及免税条件',
	'te.ma.dom.h.0': '津贴类别',
	'te.ma.dom.h.1': 'DGI免税上限',
	'te.ma.dom.h.2': '来源类型',
