	'te.ma.dom.r.0.1': '凭收据按实际费用报销，或按照DGI标准表执行 — 无固定统一上限',
	'te.ma.dom.r.0.2': '税务机关指引',
	'te.ma.dom.r.1.0': '餐费津贴（Indemnité de panier）',
	'te.ma.dom.r.1.1': '每个实际工作日MAD 30/天',
	'te.ma.dom.r.1.2': '税务机关指引',
	'te.ma.dom.r.2.0': '业务招待津贴（仅限高级员工）',
	'te.ma.dom.r.2.1': '最高为基本工资的10%',
	'te.ma.dom.r.2.2': '税务机关指引',
	'te.ma.dom.r.3.0': '交通津贴 — 城市范围内',
