	'te.ma.dom.r.6.2': '法定规定',
	'te.ma.intl.title': '国际商务出差',
	'te.ma.intl.desc': '国际商务出差适用相同的CGI框架。有文件证明且用于真实商务出差的费用报销免税。\n\n摩洛哥没有公布适用于私营部门国际出差的每日差旅津贴表。企业通常参考美国国务院或欧洲政府标准。\n\n美国国务院针对前往摩洛哥出差的2025年每日津贴标准：\n  • 卡萨布兰卡：住宿USD 199/晚 + 餐饮及杂费USD 95/天\n  • 拉巴特：住宿USD 185/晚 + 餐饮及杂费USD 94/天\n  • 马拉喀什：住宿USD 190/晚 + 餐饮及杂费USD 91/天\n\n摩洛哥员工出境出差的私营部门参考标准：\n  • 西欧（法国、西班牙、德国、英国）：USD 180–280/天\n  • 北美：USD 250–350/天\n  • 中东 / 海湾地区：USD 150–250/天\n  • 撒哈拉以南非洲：USD 100–200/天\n\n注意：摩洛哥货币为摩洛哥迪拉姆（MAD）。汇率：USD 1约等于MAD 10（2025年）。',
	'te.ma.intl.source': '国际出差：适用相同DGI框架，有文件证明的费用报销免税',
	'te.ma.intl.h.0': '目的地',
