	/* ── Netherlands (NL) ── */
	'te.nl.dom.title': '国内商务出差 — 膳宿费用补贴（Verblijfkostenvergoeding）',
	'te.nl.dom.desc': '荷兰税务局（Belastingdienst）在《工资税手册》（Handboek Loonheffingen）中公布政府规定的最高免税每日差旅津贴（verblijfkostenvergoeding）标准。该标准适用于所有雇主，并作为免税报销上限。\n\n国内膳宿费标准（2025年 — CAO Rijk，自2025年1月1日起生效）：\n\n日间补贴（出差期间）：\n  • 早餐：€4.56\n  • 午餐：€11.03\n  • 晚餐：€20.40\n  • 日间小额杂费：€4.56\n  • 夜间小额杂费：€4.56\n\n过夜补贴（每次过夜离家）：\n  • €150.30/晚（首8晚 — 正常标准）\n  • 第8晚后的小额夜间杂费：€2.28（减半）\n\n条件：\n  • 目的地必须位于不同市镇，或距离正常工作地点至少1公里\n  • 早餐、午餐及晚餐费用必须在指定场所发生\n  • 如雇主提供免费餐食：扣除相应组成部分\n  • 连续在外住宿超过8晚后：小额夜间杂费减半\n\n里程津贴（€0.23/公里）：单独计算，因公出行可完全免税。居家办公津贴：最高€2.40/天免税。',
	'te.nl.dom.source': 'CAO Rijk第10.2/10.3段 — 国内膳宿费标准；每年1月1日更新',
	'te.nl.dom.h.0': '膳宿费组成部分',
