	'te.nl.intl.title': '国际商务出差 — 境外公务出差（Buitenlandse Dienstreis）',
	'te.nl.intl.desc': '针对国际商务出差，荷兰税务局每年公布按国家划分的津贴标准。每个目的地设有两栏：\n  1. 最高住宿费用（logieskosten）\n  2. 其他费用 / 每日津贴（overige kosten）\n\n住宿标准涵盖酒店及早餐费用。\n“其他费用”标准涵盖餐费（午餐及晚餐）和小额杂费。\n\n适用与国内出差相同的扣减规则：\n  • 如提供免费餐食：扣除相应组成部分\n  • 在同一目的地连续住宿超过8晚后：小额夜间杂费减半\n\n部分主要标准（2025年 — 荷兰税务局官方表格）：\n注意：所有标准均以EUR计价。完整表格可在belastingdienst.nl查询',
