	/* ── New Zealand (NZ) ── */
	'te.nz.dom.title': '国内商务出差',
	'te.nz.dom.desc': '新西兰没有针对私营部门雇主的法定每日差旅津贴标准。新西兰税务局（IRD）采用“合理金额”标准。\n\n根据IRD指引，有两种报销方式：\n\n1. 实际费用报销：\n   • 雇主凭收据报销住宿、餐费及交通的实际费用\n   • 这些金额不属于应税收入，也不适用PAYE\n   • 如报销金额超过实际费用，超出部分须纳税\n\n2. 现金津贴（并非费用报销）：\n   • 用于餐费、住宿、服装等的固定现金付款，须作为工资通过PAYE纳税\n   • 例外情况：员工在雇主经营场所以外工作时的餐费津贴、加班餐费津贴，以及无法每日回家的员工住宿费用（例如借调、会议）— 这些通常免税\n\nIRD“合理估算”方式：\n   • 如无法取得收据，雇主可采用合理估算金额\n   • 估算必须真实反映实际费用\n   • IRD并未公布固定NZD标准 — 合理性按个案评估\n\n里程津贴：IRD公布因公使用私人车辆的里程标准（2025年：汽油、柴油或混合动力车辆在每日70公里门槛内为NZD 1.04/公里；电动车为NZD 0.35/公里）。不超过IRD标准的金额免税。\n\n2025年所得税税率（累进）：10.5% / 17.5% / 30% / 33% / 39%',
	'te.nz.dom.source': '新西兰税务局（IRD）— 员工津贴指引；按实际费用报销免税；现金津贴通过PAYE纳税',
