	'te.nz.dom.r.5.0': '里程 — 汽油/柴油/混合动力车辆（每日不超过70公里门槛）— 2025年',
	'te.nz.dom.r.5.1': 'NZD 1.04/公里（IRD公布标准）— 不超过该标准免税',
