	'te.nz.dom.r.7.2': '市场惯例',
	'te.nz.intl.title': '国际商务出差',
	'te.nz.intl.desc': '国际商务出差适用相同的IRD框架：凭收据按实际费用报销免税；固定现金津贴作为工资纳税。\n\n新西兰外交贸易部（MFAT）每日津贴表：\n   • 每季度公布；以联合国开发计划署每日生活津贴（UNDP DSA）标准为基础\n   • 适用于政府官员及MFAT签约的发展合作工作人员\n   • 以NZD计价；已公布自2026年1月1日起生效的标准表\n   • 以一项综合每日标准涵盖餐费、住宿及杂费\n\n私营部门参考：许多新西兰企业采用MFAT或美国国务院每日津贴标准作为国际差旅政策的参考基准。\n\n自2026年1月起生效的部分MFAT标准（NZD/天 — 综合标准，包括住宿、餐费及杂费）：\n   • 澳大利亚（悉尼/堪培拉/墨尔本）：NZD 400–500/天\n   • 英国：NZD 450–600/天\n   • 美国：NZD 500–700/天\n   • 新加坡：NZD 350–450/天\n   • 日本：NZD 350–500/天\n   • 太平洋岛国：NZD 200–350/天\n\n请通过mfat.govt.nz核实当前标准（每季度更新）。',
	'te.nz.intl.source': '新西兰外交贸易部（MFAT）— 每日津贴表按季度更新；以UNDP DSA标准为基础',
