	/* ── Nigeria (NG) ── */
	'te.ng.dom.title': '国内商务出差',
	'te.ng.dom.desc': '尼日利亚没有针对私营部门雇主的政府强制性每日差旅津贴标准。企业可自行制定差旅津贴政策。\n\n重大税制改革：《2025年尼日利亚税法》（NTA）\n  • 由总统蒂努布于2025年6月26日签署\n  • 自2026年1月1日起生效\n  • 取代并整合《个人所得税法》（PITA）及其他法律\n\n根据《2025年尼日利亚税法》的商务差旅税务处理：\n  • 真实且有文件证明的商务差旅费用报销通常仍免税\n  • NTA扩大应税收入范围，但对有文件支持的实际商务费用报销继续维持免税处理\n  • 无文件证明的固定现金津贴可能被视为应税雇佣收入\n\n新的个人所得税结构（自2026年1月1日起生效）：\n  • 年收入不超过NGN 800,000：0%（完全免税 — 取代此前NGN 300,000的门槛）\n  • NGN 800,001–3,000,000：适用较低累进税率\n  • 超过NGN 50,000,000：25%（最高税率）\n  • 综合减免津贴（CRA）取消；改为租金减免（年度租金的20%，最高NGN 500,000）\n\n最低工资（自2024年5月1日起）：NGN 70,000/月\nNGN汇率：USD 1约等于NGN 1,550–1,600（2025年 — 波动较大；请通过尼日利亚中央银行核实）',
	'te.ng.dom.source': 'NTA取代PITA（《个人所得税法》）；真实商务差旅费用报销通常免税',
	'te.ng.dom.h.0': '类别',
