	'te.ng.dom.r.1.1': '如属真实费用且有文件证明，根据《2025年尼日利亚税法》免税',
	'te.ng.dom.r.1.2': '税务机关指引',
	'te.ng.dom.r.2.0': '无文件证明的固定现金津贴',
