	'te.ng.dom.r.6.2': '法定规定',
	'te.ng.intl.title': '国际商务出差',
	'te.ng.intl.desc': '国际商务出差适用相同的《2025年尼日利亚税法》框架。有文件证明的真实差旅费用报销免税。\n\n美国国务院针对前往尼日利亚出差的2025年每日津贴标准：\n  • 拉各斯：住宿USD 261/晚 + 餐饮及杂费USD 126/天\n  • 阿布贾：住宿USD 168/晚 + 餐饮及杂费USD 88/天\n\n尼日利亚员工出境出差的私营部门参考标准：\n  • 英国 / 西欧：USD 250–380/天\n  • 美国：USD 280–400/天\n  • 海湾国家（阿联酋、沙特阿拉伯）：USD 180–280/天\n  • 南非 / 非洲区域：USD 120–200/天\n\n注意：尼日利亚石油和天然气行业通常采用较高的每日差旅津贴标准，以反映该行业的国际流动性。往返尼日尔三角洲或海上平台的派遣人员，通常还会另行获得艰苦地区津贴。',
	'te.ng.intl.source': '国际出差：适用相同NTA框架 — 有文件证明的差旅费用报销免税',
	'te.ng.intl.h.0': '目的地 / 类别',
	'te.ng.intl.h.1': '标准 / 备注',
	'te.ng.intl.h.2': '来源类型',
	'te.ng.intl.r.0.0': '拉各斯 — 入境（美国国务院2025年标准）',
	'te.ng.intl.r.0.1': '住宿：USD 261/晚 + 餐饮及杂费：USD 126/天',
	'te.ng.intl.r.0.2': '政府参考标准',
	'te.ng.intl.r.1.0': '阿布贾 — 入境（美国国务院2025年标准）',
	'te.ng.intl.r.1.1': '住宿：USD 168/晚 + 餐饮及杂费：USD 88/天',
	'te.ng.intl.r.1.2': '政府参考标准',
