	/* ── Norway (NO) ── */
	'te.no.dom.title': '国内商务出差 — 膳食津贴（Kostgodtgjorelse）',
	'te.no.dom.desc': '挪威由税务局（Skatteetaten）公布政府规定的最高免税每日差旅津贴（kostgodtgjorelse）标准。适用以下两个来源：\n\n1. 国家标准（Statens reiseregulativ / SGS-1001）：政府雇员必须遵守，并作为参考基准。\n2. 挪威税务局预支标准：任何私营部门雇主在无需预扣税的情况下可免税支付的最高金额。\n\n2025年国内免税标准（挪威税务局）：\n  • 出差超过12小时（不过夜）：NOK 906/天\n  • 出差6至12小时：NOK 504/天\n  • 不足6小时：无免税每日差旅津贴\n\n过夜住宿 — 住宿类型决定适用标准：\n  • 酒店且不含餐食：适用全额膳食津贴标准\n  • 酒店含早餐：扣除早餐部分（约减少20%）\n  • 私人住宿（无凭证夜间补贴）：NOK 435/晚（在每日津贴之外另行支付 — 员工无需提供收据即可保留）\n\n适用条件：\n  • 出差目的地必须距离员工住所超过15公里\n  • 且出差时间必须超过6小时\n  • 过夜住宿：员工必须在22:00–06:00期间至少有5小时不在住所\n\n24个月规则：在同一地点享受免税每日差旅津贴的期限最长为24个月。超过24个月后，扣除及免税处理方式将发生变化。\n\n里程津贴：因公使用自有车辆可免税报销NOK 3.50/公里。',
	'te.no.dom.source': '挪威税务局（Skatteetaten）— 2025年免税每日差旅津贴标准：超过12小时NOK 906/天；6至12小时NOK 504/天',
