	'te.no.dom.r.10.2': '法定规定',
	'te.no.intl.title': '国际商务出差',
	'te.no.intl.desc': '针对国际出差，挪威税务局每年公布按国家划分的每日差旅津贴标准。这些标准是任何雇主可免税支付的最高金额。\n\n国际出差主要规则：\n  • 如连续在同一目的地停留超过28天：自第29天起，每日差旅津贴降至该国家标准的75%\n  • 如同一任务地点的两次连续停留合计超过28天，同样适用该折减\n  • 无凭证夜间补贴NOK 435不适用于境外私人住宿\n\n部分国际标准（2025年 — 挪威税务局 / SGS-1001）：\n注意：国际标准通常以目的地当地货币或EUR/USD计价。除非另有说明，下列标准均为挪威税务局公布的NOK/天。',
	'te.no.intl.source': '国际出差：按国家划分标准；在同一地点自第29天起降低25%',
