	/* ── Pakistan (PK) ── */
	'te.pk.dom.title': '国内商务出差 — 差旅津贴/每日津贴（T.A./D.A.）',
	'te.pk.dom.desc': '巴基斯坦没有针对私营部门雇主的政府强制性每日差旅津贴标准。企业可自行制定T.A./D.A.（差旅津贴 / 每日津贴）政策。\n\n根据《2001年所得税条例》第12条的税务处理：\n  • 为满足员工履行雇佣职责时完全且必要发生的费用而提供的任何津贴或福利（娱乐津贴或交通津贴除外）均免税\n  • 该条例明确将T.A./D.A.（差旅津贴和每日津贴）列为此类免税津贴的示例\n  • 该津贴必须用于真实且与雇佣职责相关的差旅\n  • 超出实际需要或并非用于商务目的的金额可能须纳税\n\n其他免税津贴（第12条及第二附表）：\n  • 医疗津贴：最高为基本工资的10%或PKR 10,000/月，以较低者为准\n  • 交通津贴：如车辆仅用于商务用途，则不产生应税福利\n  • 房租津贴：基本工资的45%（常见市场惯例，实际可能有所不同）\n\n所得税（《2001年所得税条例》，2025-26税年 — 2025年7月至2026年6月）：\n  • 不超过PKR 600,000：0%\n  • PKR 600,001–1,200,000：超过PKR 600,000部分的1%\n  • PKR 1,200,001–2,200,000：PKR 6,000 + 11%\n  • PKR 2,200,001–3,200,000：PKR 116,000 + 23%\n  • PKR 3,200,001–4,100,000：PKR 346,000 + 30%\n  • 超过PKR 4,100,000：PKR 616,000 + 35%\n\n税务年度：7月1日至次年6月30日。PKR汇率：USD 1约等于PKR 278–285（2025年）。',
	'te.pk.dom.source': '第12条（薪资收入）— 因履行公务而支付的T.A./D.A.（差旅津贴/每日津贴）免税',
