	'te.pk.dom.r.6.0': '政府参考标准 — BPS 1-15（辅助人员）',
	'te.pk.dom.r.6.1': '折合USD 120–180/天',
	'te.pk.dom.r.6.2': '政府参考标准',
	'te.pk.intl.title': '国际商务出差',
	'te.pk.intl.desc': '从巴基斯坦出发的国际商务出差适用相同的《2001年所得税条例》框架。因境外公务而支付的T.A./D.A.免税。\n\n政府参考标准：巴基斯坦联邦政府根据公务员职级及目的地国家，规定境外出差待遇。相关标准由财政司公布，并按基本薪级（BPS）划分。\n  • 高级官员（BPS 20-22）：USD 220–350/天\n  • 中级官员（BPS 16-19）：USD 170–270/天\n  • 辅助人员（BPS 1-15）：USD 120–180/天\n\n美国国务院针对前往巴基斯坦出差的2025年每日津贴标准：\n  • 伊斯兰堡：住宿USD 159/晚 + 餐饮及杂费USD 77/天\n  • 卡拉奇：住宿USD 155/晚 + 餐饮及杂费USD 78/天\n  • 拉合尔：住宿USD 120/晚 + 餐饮及杂费USD 65/天\n\n注意：巴基斯坦属于较高安全风险环境；许多跨国企业会针对卡拉奇、拉合尔及敏感地区采用较高的每日差旅津贴及艰苦地区津贴。',
	'te.pk.intl.source': '国际出差：适用相同的《2001年所得税条例》框架 — 有文件证明且用于公务的差旅津贴免税',
