	/* ── Peru (PE) ── */
	'te.pe.dom.title': '国内商务出差 — 差旅费（Viaticos）',
	'te.pe.dom.desc': '秘鲁根据税法及单独的公共部门法令监管差旅费（viaticos）。私营部门适用秘鲁国家税务管理局（SUNAT）的所得税规则；私营部门雇主没有固定的强制性每日差旅津贴标准。\n\n根据《所得税法》的税务处理：\n  • 商务差旅费用（viaticos — 包括住宿、餐费及交通）在符合以下条件时不视为员工的应税收入：\n    1. 仅用于支付履行职责时必要发生的费用\n    2. 有付款凭证（comprobantes de pago，即税务收据/电子发票）充分证明\n    3. 金额合理且并非为逃税而安排\n\nSUNAT文件要求：\n  • 私营部门：国内出差差旅费必须有SUNAT认可的付款凭证支持。如无收据，雇主不得在企业所得税中扣除相关费用，且员工可能被视为取得应税收入\n  • 无收据的交通费（movilidad）：每名员工每日最高为月度最低生活工资（RMV）的4%（2025年：PEN 1,130的4% = PEN 45.20/天）\n\n公共部门参考标准（第007-2013-EF号最高法令）：\n  • PEN 320/天 — 政府雇员国内出差差旅费最高标准\n  • 适用于所有公务员在秘鲁境内执行公务任务\n\n2025年税务单位（UIT）：PEN 5,350\n所得税免税额（第五类收入 — Quinta Categoria）：\n  • 年度雇佣收入的首7个UIT免税：7 x PEN 5,350 = PEN 37,450/年\n  • 超出部分个人所得税税率：8% / 14% / 17% / 20% / 30%\n自2025年1月1日起的最低工资（RMV）：PEN 1,130/月',
	'te.pe.dom.source': '第007-2013-EF号最高法令：公共部门国内差旅费上限PEN 320/天；私营部门：凭付款凭证按实际费用报销',
