	'te.pe.intl.title': '国际商务出差',
	'te.pe.intl.desc': '针对国际差旅费，秘鲁通过第056-2013-PCM号最高法令规定公共部门标准表，并按地理区域设定每日上限。\n\n公共部门国际差旅费（第056-2013-PCM号最高法令 — 各区域以USD/天计价）：\n  • A区（美国、加拿大、日本、西欧、澳大利亚）：高级官员USD 440/天\n  • A区（普通员工）：USD 200/天\n  • B区（拉丁美洲、东欧及亚洲大部分地区）：普通员工USD 160/天\n  • C区（非洲、中亚）：USD 100/天\n\n私营部门：无强制性标准。凭收据按实际费用报销的金额免税。企业通常参考公共部门标准或美国国务院标准。\n\n美国国务院针对前往秘鲁出差的2025年每日津贴标准：\n  • 利马：住宿USD 197/晚 + 餐饮及杂费USD 95/天\n  • 秘鲁其他地区：住宿USD 130/晚 + 餐饮及杂费USD 75/天\n\n注意：SUNAT实施电子发票制度（comprobantes electronicos）— 应保留国际住宿费用收据，以确保企业可进行税务扣除。',
	'te.pe.intl.source': '美国国务院2025年标准：利马住宿USD 197 + 餐饮及杂费USD 95/天（广泛用作私营部门参考标准）',
