	/* ── Philippines (PH) ── */
	'te.ph.dom.title': '国内商务出差',
	'te.ph.dom.desc': '菲律宾没有针对私营部门雇主的政府强制性每日差旅津贴标准。私营部门可自行设定标准，税务处理则由菲律宾国税局（BIR）监管。\n\n根据经修订的BIR第2-98号税收条例及BIR第008-2023号裁定的税务处理：\n  • 向员工支付的每日差旅津贴，如属于员工履行职责时发生的真实、正常且必要的差旅及业务招待费用预付款或报销款，则无需缴纳薪酬预扣税（WTC）\n  • 该规定同时适用于普通员工及管理人员/主管人员\n  • 享受免税待遇的条件：\n    1. 相关费用属于开展贸易或业务时正常且必要的费用\n    2. 员工必须对预付款进行核算或清算\n    3. 多余预付款必须退还雇主\n    4. 相关费用必须有收据或文件充分证明\n\n政府参考标准（2019年第77号行政命令 — 取代第248号/第298号行政命令）：\n  • 政府雇员国内每日差旅津贴按地区组别划分：\n    - 第一组（马尼拉大都会及高成本地区）：PHP 800/天\n    - 第二组（中等成本地区）：PHP 600/天\n    - 第三组（低成本地区）：PHP 400/天\n  • 构成比例：住宿50%、餐费30%、杂费20%\n\n所得税（《税收改革促进包容法》，第10963号共和国法）：\n  • 累进税率：不超过PHP 250,000适用0% | PHP 250K–400K适用20% | PHP 400K–800K适用25% | PHP 800K–2M适用30% | PHP 2M–8M适用32% | 超过PHP 8M适用35%\n  • 第13个月工资及最低限额福利合计每年最高PHP 90,000免税',
	'te.ph.dom.source': '第2-98号税收条例：为履行职责而发生的真实商务费用每日差旅津贴无需缴纳薪酬预扣税',
	'te.ph.dom.h.0': '类别',
	'te.ph.dom.h.1': '标准 / 税务处理',
	'te.ph.dom.h.2': '来源类型',
	'te.ph.dom.r.0.0': '私营部门每日差旅津贴 — 真实商务出差',
	'te.ph.dom.r.0.1': '如已妥善清算并提供文件证明，则无需缴纳WTC（BIR第2-98号税收条例）',
	'te.ph.dom.r.0.2': '税务机关指引',
	'te.ph.dom.r.1.0': '未清算的多余预付款 / 非商务用途金额',
	'te.ph.dom.r.1.1': '视为应税薪酬 — 须缴纳WTC及所得税',
	'te.ph.dom.r.1.2': '法定规定',
