	'te.ph.dom.r.6.0': '所得税税率（《税收改革促进包容法》— 第10963号共和国法）',
	'te.ph.dom.r.6.1': '不超过PHP 250K适用0%；超过部分适用20%–35%累进税率',
	'te.ph.dom.r.6.2': '法定规定',
	'te.ph.intl.title': '国际商务出差',
	'te.ph.intl.desc': '国际商务出差适用相同的BIR第2-98号税收条例框架。因履行商务职责而真实发生并有文件证明的差旅费用报销免税。\n\n政府参考标准（2019年第77号行政命令 — 政府雇员国际出差）：\n  • 根据经修订的第248号行政命令：差旅津贴USD 100/天 + 酒店房费USD 200/晚\n  • 发展合作工作采用联合国开发计划署每日生活津贴标准\n\n美国国务院针对前往菲律宾出差的2025年每日津贴标准：\n  • 马尼拉：住宿USD 208/晚 + 餐饮及杂费USD 101/天\n  • 菲律宾其他地区：标准较低 — 请通过美国国务院查询具体地点\n\n菲律宾雇佣员工出境出差的私营部门参考标准：\n  • 美国 / 西欧：USD 280–400/天\n  • 日本 / 新加坡 / 澳大利亚：USD 250–350/天\n  • 中东 / 海湾地区：USD 180–280/天\n  • 亚洲区域内：USD 150–250/天\n\n注意：向管理人员或主管人员提供的附加福利（按BIR定义）须按总额还原后的货币价值缴纳35%的附加福利税（FBT），而非WTC。真实的差旅费用报销不计入FBT。',
	'te.ph.intl.source': '2019年第77号行政命令：整合政府差旅规则；私营部门每日差旅津贴由公司政策规定',
	'te.ph.intl.h.0': '目的地 / 类别',
