	/* ── Poland (PL) ── */
	'te.pl.dom.title': '国内商务出差 — 国内每日差旅津贴（Dieta Krajowa）',
	'te.pl.dom.desc': '波兰根据《劳动法典》第775条及2013年1月29日部长条例（Rozporzadzenie MPiPS，Dz.U. 2023，poz. 2190），规定了员工商务出差的法定最低每日差旅津贴（dieta）标准。该条例规定的标准是公共部门必须遵守的最低标准，同时也是私营部门的免税参考上限。\n\n现行国内每日差旅津贴（自2023年1月1日起）：\n  • PLN 45/天 — 法定最低标准，同时也是私营部门雇主享受个人所得税及ZUS社会保险免税待遇的上限\n  • 拟议提高：劳动部条例草案建议将国内每日差旅津贴提高至PLN 60/天。截至2026年年中，该草案仍处于立法程序中 — 应用前请核实当前金额\n\n出差时长标准：\n  • 不超过8小时：每日差旅津贴的50% = PLN 22.50（拟议：PLN 30）\n  • 8至12小时：全额每日差旅津贴 = PLN 45（拟议：PLN 60）\n  • 超过12小时：全额每日差旅津贴 = PLN 45（拟议：PLN 60）\n\n如雇主提供免费餐食，每日差旅津贴相应扣减：\n  • 免费早餐：全额每日差旅津贴扣减25%\n  • 免费午餐：扣减50%\n  • 免费晚餐：扣减25%\n\n住宿（nocleg）：\n  • 凭收据按实际费用报销，或在无收据的情况下按每日差旅津贴的150%支付固定住宿津贴 = PLN 67.50/晚（拟议：PLN 90）\n\n税务/ZUS处理：\n  • 不超过PLN 45/天上限：完全免征个人所得税及ZUS缴费\n  • 超过PLN 45/天：超出部分属于应税收入，并须缴纳ZUS缴费\n  • 私营部门可支付更高金额，但仅不超过PLN 45的部分免征个人所得税及ZUS\n\n里程津贴：排量不超过900cc的汽车为PLN 0.89/公里；排量超过900cc的汽车为PLN 1.15/公里。',
	'te.pl.dom.source': '国内每日差旅津贴：自2023年1月1日起为PLN 45/天。截至2026年年中，拟提高至PLN 60/天的方案仍待立法通过。',
