	'te.pl.intl.title': '国际商务出差 — 境外每日差旅津贴（Dieta Zagraniczna）',
	'te.pl.intl.desc': '针对国际商务出差，波兰采用2013年1月29日MPiPS条例附件中规定的国家特定标准。每个国家均设有：\n  1. 每日差旅津贴（餐费/杂费津贴）— 以EUR、USD或当地货币计价\n  2. 住宿上限（Limit za nocleg）— 按每晚计算\n\n出差时长标准（与国内出差逻辑相同）：\n  • 在境外不足8小时：适用该国家每日差旅津贴的1/3\n  • 8至12小时：适用该国家每日差旅津贴的1/2\n  • 超过12小时：适用全额每日差旅津贴\n\n如提供免费餐食：\n  • 提供早餐：全额每日差旅津贴扣减15%\n  • 提供午餐：扣减30%\n  • 提供晚餐：扣减30%\n\n税务/ZUS处理：适用相同规则 — 不超过已公布国家标准的金额免征个人所得税及ZUS；超过部分须纳税并缴纳相关费用。\n\n部分国家标准（2025年 — 2013年1月29日条例附件）：',
