	/* ── Portugal (PT) ── */
	'te.pt.dom.title': '国内商务出差 — 差旅补助（Ajudas de Custo）',
	'te.pt.dom.desc': '葡萄牙根据经修订的第106/98号法令规定差旅补助（ajudas de custo）。这些标准直接适用于公共部门，同时也是私营部门雇主享受个人所得税及TSU社会缴费免税待遇的上限。\n\n重要更新：2025年1月16日第1/2025号法令将国内标准提高5%，并自2025年1月1日起生效。\n\n2025年国内标准（葡萄牙大陆及自治区）：\n  全日标准（涉及过夜住宿或整个工作日离开工作地点）：\n    • 普通员工：EUR 50.20/天\n    • 政府成员：EUR 65.89/天\n\n  部分日标准（不过夜）：\n    • 午餐（13:00–14:00）：每日标准的25% = EUR 12.55\n    • 晚餐（20:00–21:00）：每日标准的25% = EUR 12.55\n    • 如晚上22:00前无法返回住所：额外支付50%\n\n  仅餐费（不过夜）：EUR 22.30/天\n  仅住宿：EUR 27.70/天\n\n里程津贴：因公使用私家车为EUR 0.40/公里（不超过该标准免税）\n\n税务处理：\n  • 不超过法令规定上限的金额：免征个人所得税及TSU社会保障缴费\n  • 超过上限的金额：视为应税雇佣收入，并须缴纳社会保障费用\n  • 私营部门可采用政府标准或其他金额，但仅法定上限内的金额可免征个人所得税及TSU\n\n2025年最低工资（SMN）：葡萄牙大陆地区为EUR 870/月',
	'te.pt.dom.source': '经第1/2025号法令修订的1998年4月24日第106/98号法令：公共部门参考标准同时作为私营部门个人所得税及TSU免税上限',
	'te.pt.dom.h.0': '类别',
	'te.pt.dom.h.1': '标准（EUR — 2025年）',
