	'te.pt.dom.r.6.0': '夜间补贴（晚上22:00前无法返回住所）',
	'te.pt.dom.r.6.1': '在适用标准基础上额外支付50%',
	'te.pt.dom.r.6.2': '法定规定',
	'te.pt.dom.r.7.0': '里程津贴 — 私家车',
	'te.pt.dom.r.7.1': 'EUR 0.40/公里（不超过该标准免税）',
	'te.pt.dom.r.7.2': '法定规定',
	'te.pt.dom.r.8.0': '超过第106/98号法令上限的金额',
	'te.pt.dom.r.8.1': '属于个人所得税应税收入，并须缴纳TSU社会缴费',
	'te.pt.dom.r.8.2': '法定规定',
	'te.pt.intl.title': '国际商务出差',
	'te.pt.intl.desc': '针对国际差旅补助，相关标准由部长令制定，并更新第106/98号法令中引用的国家特定金额。第1/2025号法令发布后，2025年国际标准将通过另一项部长令更新 — 请通过dre.pt核实最新公布金额。\n\n2024/2025年参考标准（来源于第106/98号法令及此前部长令 — 等待2025年更新）：\n  • 餐费及住宿合计：EUR 89.35/天\n  • 仅餐费（境外）：EUR 37.19/天\n  • 仅住宿（境外）：EUR 52.16/天\n\n以上为国际出差可享受个人所得税及TSU免税待遇的最高上限。\n\n美国国务院针对前往葡萄牙出差的2025年每日津贴标准：\n  • 里斯本：住宿USD 232/晚 + 餐饮及杂费USD 100/天\n  • 波尔图 / 其他地区：标准较低 — 请通过美国国务院查询详细信息\n\n电子发票说明：自2025年1月起，葡萄牙要求所有PDF发票附有合格电子签名 — 应确保国际差旅费用收据符合新的电子发票规则及SAF-T合规要求。',
	'te.pt.intl.source': '国际标准：第106/98号法令规定境外差旅补助上限，并由单独的部长令更新；私营部门以此作为参考',
