	/* ── Romania (RO) ── */
	'te.ro.dom.title': '国内商务出差 — 每日差旅津贴（Diurna）',
	'te.ro.dom.desc': '罗马尼亚设有法定国内每日差旅津贴（diurna）制度。公共部门标准由相关命令规定，私营部门雇主则适用倍数上限。\n\n现行标准（第1235/2023号命令 — 目前有效）：\n  • 公共部门每日差旅津贴：RON 23/天\n  • 私营部门最高免税上限：2.5 x RON 23 = RON 57.50/天\n\n这意味着，私营部门雇主每日支付不超过RON 57.50时，员工无需缴纳个人所得税或社会缴费（CAS/CASS）。超过RON 57.50/天的金额将被视为应税雇佣收入。\n\n员工无需为每日差旅津贴本身提供证明文件或收据 — diurna属于固定每日津贴，而非实报实销费用。\n\n其他津贴（与diurna分开计算）：\n  • 住宿：如雇主未提供住宿，可另行支付最高RON 265/天的住宿津贴，并在有收据证明的情况下免税\n  • 如已提供住宿：不得支付住宿津贴\n\n餐费扣减规则：\n  • 如雇主在出差期间提供全部餐食：每日差旅津贴扣减50%\n\n流动津贴（替代方案 — 适用于没有固定工作地点的员工）：\n  • 每月税后RON 1,000 — 免税（例如外勤销售人员）\n  • 不得与同一期间的每日差旅津贴同时领取\n\n自2025年1月1日起的最低工资：RON 4,050/月\n所得税：扣除后雇佣收入统一适用10%税率',
	'te.ro.dom.source': '私营部门：最高可按公共部门标准的2.5倍支付，即RON 57.50/天免税（在该上限内免征个人所得税及社会缴费）',
	'te.ro.dom.h.0': '类别',
	'te.ro.dom.h.1': '标准 / 金额',
	'te.ro.dom.h.2': '来源类型',
	'te.ro.dom.r.0.0': '公共部门每日差旅津贴（第1235/2023号命令）',
	'te.ro.dom.r.0.1': 'RON 23/天',
	'te.ro.dom.r.0.2': '法定规定',
	'te.ro.dom.r.1.0': '私营部门上限（公共部门标准的2.5倍）',
	'te.ro.dom.r.1.1': 'RON 57.50/天（个人所得税及社会缴费最高免税金额）',
	'te.ro.dom.r.1.2': '法定规定',
	'te.ro.dom.r.2.0': '超过RON 57.50/天的金额',
