	'te.ro.intl.title': '国际商务出差',
	'te.ro.intl.desc': '针对国际商务出差，罗马尼亚采用经修订的第518/1995号政府决定（Hotarare de Guvern）规定的目的地特定标准。\n\n同样适用2.5倍规则：\n  • 私营部门可按第518/1995号政府决定规定的国家标准支付最高2.5倍的免税金额\n  • 超过2.5倍的金额视为应税雇佣收入\n\n如雇主未在境外提供住宿：\n  • 可另行支付住宿津贴 — 按实际发生且有收据证明的费用报销，或不超过第518/1995号政府决定规定的该国家住宿上限\n\n部分国际每日差旅津贴标准（第518/1995号政府决定 — 公共部门基础标准，以EUR或USD/天计价 — 私营部门上限为这些金额的2.5倍）：',
