	/* ── Saudi Arabia (SA) ── */
	'te.sa.dom.title': '国内商务出差',
	'te.sa.dom.desc': '沙特阿拉伯不对雇佣收入征收个人所得税。员工获得的所有津贴，包括每日差旅津贴、住房津贴、交通津贴及餐费津贴，对员工而言均完全免税。私营部门雇主也无需遵循任何强制性的每日差旅津贴标准。\n\n法律框架：\n  • 《沙特劳动法》（2005年第M/51号皇家法令，经2022年第M/24号皇家法令修订）\n  • 该法律未规定私营部门出差必须支付的每日差旅津贴金额\n  • 雇主可自行制定每日差旅津贴及差旅补贴政策\n\nGOSI（社会保险）说明：\n  • 社会保险缴费按基本工资加住房津贴计算\n  • 缴费基数上限：SAR 45,000/月\n  • 沙特国民：合计21.5%（员工9.75% + 雇主11.75%）\n  • 外籍员工：职业伤害保险2%（仅由雇主缴纳）\n  • 每日差旅津贴及差旅补贴通常不计入GOSI缴费基数\n\n沙特阿拉伯私营部门常见每日差旅津贴标准：\n  • 高级管理人员：国内出差SAR 500–1,500/天\n  • 中层管理人员：SAR 300–800/天\n  • 普通员工：SAR 150–400/天\n\n增值税：沙特阿拉伯适用15%的增值税。商务差旅收据所列金额包含增值税。雇主可凭有效税务发票，就合法商务费用申报抵扣进项增值税。',
	'te.sa.dom.source': '沙特阿拉伯不征收个人所得税 — 员工获得的所有津贴，包括每日差旅津贴，对个人而言均完全免税',
