	'te.sa.dom.r.8.2': '市场惯例',
	'te.sa.intl.title': '国际商务出差',
	'te.sa.intl.desc': '对于从沙特阿拉伯出发的国际商务出差，同样适用不征收个人所得税的制度。员工获得的所有每日差旅津贴均免税。\n\n沙特阿拉伯企业通常参考美国国务院每日津贴标准或联合国国际公务员制度委员会标准制定国际差旅政策。\n\n美国国务院针对前往沙特阿拉伯出差的2025年每日津贴标准：\n  • 利雅得：住宿USD 215/晚 + 餐饮及杂费USD 98/天\n  • 吉达：住宿USD 195/晚 + 餐饮及杂费USD 96/天\n  • 达曼 / 东部省：住宿USD 185/晚 + 餐饮及杂费USD 92/天\n\n沙特阿拉伯员工出境出差的常见国际每日差旅津贴：\n  • 美国 / 西欧：USD 280–400/天\n  • 日本 / 新加坡 / 澳大利亚：USD 250–350/天\n  • 其他中东地区 / 海湾合作委员会国家：USD 180–300/天\n  • 亚太地区（不包括日本、新加坡及澳大利亚）：USD 150–250/天\n  • 非洲 / 拉丁美洲：USD 120–200/天\n\n离职福利说明：根据《沙特劳动法》，离职金仅按基本工资计算 — 每日差旅津贴及其他津贴不会增加离职金负债。',
	'te.sa.intl.source': '沙特阿拉伯不征收个人所得税 — 每日差旅津贴免税。企业可自行设定标准。GOSI缴费仅适用于基本工资及住房津贴。',
