	/* ── Serbia (RS) ── */
	'te.rs.dom.title': '国内商务出差 — 每日差旅津贴（Dnevnica）',
	'te.rs.dom.desc': '塞尔维亚根据《个人所得税法》（Zakon o porezu na dohodak gradjana）规定了法定每日差旅津贴（dnevnica）规则。免税上限根据消费者价格指数（CPI）每年调整。\n\n国内每日差旅津贴 — 免税上限：\n  • 每个完整每日差旅津贴为RSD 3,380（自2025年2月1日起生效）\n  • 按2025年汇率计算约为EUR 28–30\n  • 半日津贴（适用于较短行程）：按相应比例计算\n  • 根据统计局公布的消费者价格指数每年调整\n\n税务处理：\n  • 不超过RSD 3,380/天：免税（不计入个人所得税或社会缴费的工资基数）\n  • 超过RSD 3,380/天：超出部分视为应税雇佣收入 — 须缴纳10%的统一个人所得税及社会缴费\n\n因公使用私家车的车辆津贴：\n  • 每月最高RSD 9,855（约EUR 84）免税（自2025年2月1日起生效）\n  • 或按每单位燃油价格 x 实际耗油量的30%计算 — 以较低者为准\n\n2025年个人所得税：在扣除每月RSD 28,423（约EUR 240）的免税额后，雇佣收入统一适用10%税率。另行适用累进年度个人所得税：年度收入为平均工资的3至6倍时适用10%；超过6倍时适用15%。',
	'te.rs.dom.source': '国内每日差旅津贴免税上限：自2025年2月1日起为RSD 3,380/天（约EUR 29），每年根据消费者价格指数调整。来源：KPMG Serbia GMS Flash Alert 2025。',
