	'te.rs.dom.r.5.2': '法定规定',
	'te.rs.intl.title': '国际商务出差',
	'te.rs.intl.desc': '重大变化：国际每日差旅津贴的免税上限自2025年1月1日起大幅提高。\n\n国际每日差旅津贴 — 免税上限：\n  • EUR 90/天（此前为EUR 50/天）\n  • 该标准适用于塞尔维亚境外商务出差的完整每日津贴\n  • 超过EUR 90/天的任何金额均视为应税雇佣收入\n\n税务处理：\n  • 不超过EUR 90/天：免税 — 不计入工资或社会缴费基数\n  • 超过EUR 90/天：超出部分须缴纳10%的个人所得税及社会缴费\n\n该变化由修订《个人所得税法》的法律引入，并刊登于塞尔维亚第94/2024号《官方公报》，自2025年1月1日起生效。\n\n私营部门惯例：许多塞尔维亚雇主此前已经支付高于旧EUR 50上限的金额，并对超出部分纳税。新的EUR 90上限使塞尔维亚标准更接近欧洲普遍水平，从而降低经常国际出差员工的税务负担。\n\n住宿及交通费用：凭收据按实际费用另行报销；不计入每日差旅津贴上限。',
	'te.rs.intl.source': '国际出差：自2025年1月1日起，EUR 90/天免税（经法律修订由EUR 50提高）。来源：KPMG Serbia、Zunic Law。',
	'te.rs.intl.h.0': '类别',
	'te.rs.intl.h.1': '标准 / 金额',
