	/* ── Singapore (SG) ── */
	'te.sg.dom.title': '国内商务出差 — 新加坡',
	'te.sg.dom.desc': '新加坡税务局（IRAS）公布每日差旅津贴的“可接受标准”。这些标准是可免税支付的最高每日金额。支付超过该标准的金额并不要求员工提供收据，但超出部分将成为应税收入，并必须在IR8A表格中申报。\n\n新加坡国内标准（2025年）：\n  • 新加坡雇佣的员工在新加坡境内因公出差：SGD 150/天免税\n  • 海外雇佣的员工前往新加坡因公出差：SGD 160/天免税\n\n主要规则：\n  • 该标准仅适用于餐费及杂费，不包括住宿或机票\n  • 由雇主直接支付或根据实际收据报销的住宿费用不属于每日差旅津贴，因此免税\n  • 机场接送、城市间商务交通及商务招待费用不属于每日差旅津贴 — 按实际费用报销时免税\n  • 如员工在同一天内前往多个国家：采用员工当天停留时间最长的国家标准\n\n如雇主在某次出差中支付的金额低于可接受标准：不足金额不得用于抵销另一次出差产生的应税超额部分。\n\n雇主可提交由咨询公司提供的生活成本数据，申请IRAS重新审核标准（不接受公司自身经验作为依据）。\n\n新加坡雇佣收入的首SGD 20,000无需缴纳所得税。居民适用0%–24%的累进税率；非居民适用15%或累进税率，以较高者为准。',
	'te.sg.dom.source': '新加坡税务局（IRAS）— 每日差旅津贴可接受标准；每年12月公布，并自次年1月1日起生效',
