	'te.sg.dom.r.4.2': '税务机关指引',
	'te.sg.intl.title': '国际每日差旅津贴 — IRAS 2025年可接受标准（SGD/天）',
	'te.sg.intl.desc': '针对国际出差，新加坡税务局每年公布按国家划分的可接受标准（每年12月公布，自次年1月1日起生效）。这些标准是新加坡雇佣员工海外商务出差可享受的最高免税每日津贴金额。\n\n下表列出IRAS 2025年可接受标准（SGD/天）— 来源：IRAS官方PDF（2024年12月公布，自2025年1月1日起生效）。\n\n超过可接受标准的金额 = 应税收入 → 在IR8A表格中申报。\n不超过可接受标准的金额 = 免税，无需申报。',
