	/* ── Slovakia (SK) ── */
	'te.sk.dom.title': '国内商务出差 — 每日差旅津贴（Dieta）',
	'te.sk.dom.desc': '斯洛伐克根据《差旅津贴法》（Zakon c. 283/2002 Z.z. o cestovnych nahradach）规定了法定每日差旅津贴（dieta）标准。相关标准会通过部长令定期更新。\n\n现行国内标准（自2025年12月1日起生效 — 斯洛伐克劳动部）：\n  • 出差5至12小时：EUR 9.30\n  • 出差12至18小时：EUR 13.80\n  • 出差超过18小时：EUR 20.60\n  • 出差不足5小时：无权领取每日差旅津贴\n\n餐费扣减（如雇主提供免费餐食）：\n  • 免费早餐：适用每日差旅津贴扣减25%\n  • 免费午餐：扣减40%\n  • 免费晚餐：扣减40%\n\n税务处理：\n  • 不超过法定每日差旅津贴标准的金额：免征个人所得税及社会保险和医疗保险缴费\n  • 超过法定标准的金额：视为应税雇佣收入\n\n住宿：凭收据按实际费用报销 — 与每日差旅津贴分开计算。\n\n2025年个人所得税：年收入不超过EUR 47,537.98适用19%；超过部分适用25%。\n2025年最低工资：EUR 816/月。',
	'te.sk.dom.source': '自2025年12月1日起的国内每日差旅津贴：5至12小时 = EUR 9.30；12至18小时 = EUR 13.80；超过18小时 = EUR 20.60（斯洛伐克劳动部命令）',
	'te.sk.dom.h.0': '出差时长 / 类别',
	'te.sk.dom.h.1': '每日差旅津贴（EUR — 自2025年12月1日起生效）',
