	'te.sk.intl.title': '国际商务出差 — 境外每日差旅津贴（Dieta Zahranicna）',
	'te.sk.intl.desc': '针对国际商务出差，斯洛伐克根据《差旅津贴法》规定按国家划分的每日差旅津贴标准。相关标准由劳动和社会事务部制定，并每年更新。\n\n国际每日差旅津贴的时长标准：\n  • 超过12至24小时：全额每日差旅津贴（100%）\n  • 超过6至12小时：半额每日差旅津贴（50%）\n  • 不超过6小时：如实际发生费用，可领取三分之一每日差旅津贴，否则无津贴\n\n餐费扣减（如在境外提供免费餐食）：\n  • 免费早餐：适用每日差旅津贴扣减25%\n  • 免费午餐：扣减40%\n  • 免费晚餐：扣减40%\n\n部分国际标准（依据斯洛伐克劳动部措施 — 全日标准，以每日相应货币计价）：',
	'te.sk.intl.source': '国际每日差旅津贴标准由劳动和社会事务部每年制定；按目的地国家分别规定（EUR、USD、GBP、CHF等）',
