	/* ── Slovenia (SI) ── */
	'te.si.dom.title': '国内商务出差 — 每日差旅津贴（Dnevnica）',
	'te.si.dom.desc': '斯洛文尼亚规定了法定每日差旅津贴（dnevnica）标准。私营部门雇主适用的免税上限由《费用报销税务处理条例》（Uredba o davchni obravnavi povracil stroshkov）规定。\n\n国内每日差旅津贴标准（2025年 — 私营部门免税上限）：\n  • 离开超过12小时：EUR 27.81\n  • 离开8至12小时：EUR 13.88\n  • 离开6至8小时：EUR 9.69\n  • 离开不足6小时：无权领取每日差旅津贴\n\n餐费扣减（如雇主提供免费餐食）：\n  • 免费早餐：全日每日差旅津贴（超过12小时标准）扣减10%；8至12小时标准扣减15%\n  • 免费午餐：超过12小时扣减35%；8至12小时扣减40%\n  • 免费晚餐：超过12小时扣减35%；8至12小时扣减40%\n  • 扣减总额设有上限：员工始终至少保留每日差旅津贴的20%\n\n税务处理：\n  • 不超过法定上限：免征个人所得税及社会缴费\n  • 超过法定上限：视为应税雇佣收入\n\n住宿：凭收据按实际费用报销。\n里程津贴：因公使用私家车，自2026年起为EUR 0.43/公里。\n\n2025年个人所得税税率（累进）：16%–50%\n  • 年收入不超过EUR 9,566：16%\n  • EUR 9,567–26,046：26%\n  • EUR 26,047–51,886：33%\n  • EUR 51,887–74,160：39%\n  • 超过EUR 74,160：50%',
	'te.si.dom.source': '国内每日差旅津贴：超过12小时 = EUR 27.81；8至12小时 = EUR 13.88；6至8小时 = EUR 9.69（2025年免税上限）',
	'te.si.dom.h.0': '出差时长 / 类别',
	'te.si.dom.h.1': '每日差旅津贴（EUR — 2025年）',
	'te.si.dom.h.2': '来源类型',
	'te.si.dom.r.0.0': '离开超过12小时',
