	'te.si.dom.r.8.0': '超过法定上限的金额',
	'te.si.dom.r.8.1': '视为应税雇佣收入 — 须缴纳个人所得税及社会缴费',
	'te.si.dom.r.8.2': '法定规定',
	'te.si.intl.title': '国际商务出差 — 境外每日差旅津贴（Dnevnica v Tujini）',
	'te.si.intl.desc': '针对国际商务出差，斯洛文尼亚根据《境外差旅费用报销条例》采用按国家划分的每日差旅津贴标准。\n\n新规定：Ur. l. RS 102/2025（自2026年1月1日起生效）对国际出差采用了新的时长标准，并修订了国家费率表。\n\n国际每日差旅津贴时长标准（新标准 — 自2026年1月1日起）：\n  • 超过14至24小时：适用国家标准的100%\n  • 超过8至14小时：适用国家标准的75%\n  • 超过6至8小时：适用国家标准的25%\n  • 不足6小时：无每日差旅津贴\n\n此前标准（2026年前）：超过14小时 / 8至14小时 / 不足8小时\n\n境外餐费扣减（根据新规定）：\n  • 超过14小时的出差：早餐扣减10%，午餐扣减35%，晚餐扣减35%\n  • 8至14小时的出差：早餐扣减15%，午餐扣减40%，晚餐扣减40%\n  • 最高扣减比例：80%（员工至少保留20%）\n\n部分主要国家标准（EUR或USD/天 — 来源于Ur. l. RS 102/2025）：\n私营部门将这些标准作为免税上限。',
	'te.si.intl.source': '新的境外差旅规定自2026年1月1日起生效 — 更新时长标准及按国家划分的每日差旅津贴表；取代2019年规定',
