	/* ── South Africa (ZA) ── */
	'te.za.dom.title': '国内商务出差 — 膳宿津贴',
	'te.za.dom.desc': '南非税务局（SARS）根据《1962年第58号所得税法》第8(1)条公布了膳宿津贴的“视同金额”标准。该标准通常由财政部长在预算演讲期间每年更新，并自3月1日（南非税务年度开始日）起生效。\n\n国内标准（2026税年 — 自2025年3月1日起生效）：\n  • 仅杂费：ZAR 176/天（由ZAR 169提高）\n  • 餐费及杂费合计：ZAR 570/天（由ZAR 548提高）\n\n视同金额的运作方式：\n  • 员工必须因工作需要在通常住所之外至少住宿一晚\n  • 不超过视同金额：免税 — 无需提供收据\n  • 超过视同金额：超出部分须纳税（计入年度纳税申报，而非每月通过PAYE扣缴）\n  • 员工也可选择申报实际费用（须提供收据），以减少应税金额\n\n住宿说明：\n  • SARS并未公布住宿费用的视同标准\n  • 住宿费用报销必须有收据证明，方可免税\n  • 任何无凭证的住宿津贴均须纳税\n\nIRP5代码：\n  • 代码3705：本地差旅膳宿津贴（免税）\n  • 代码3704：本地差旅膳宿津贴（应税 — 超过视同标准）\n\n2025年个人所得税：18%–45%累进税率。\n税务年度：每年3月1日至次年2月底。\n2025年最低工资：ZAR 28.79/小时（按每周40小时计算，每月约ZAR 4,969）。',
	'te.za.dom.source': '南非税务局（SARS）—《1962年第58号所得税法》第8(1)条；2026税年标准（自2025年3月1日起生效）',
	'te.za.dom.h.0': '类别',
	'te.za.dom.h.1': '视同金额（ZAR/天 — 2026税年）',
	'te.za.dom.h.2': '来源类型',
	'te.za.dom.r.0.0': '仅杂费 — 国内',
	'te.za.dom.r.0.1': 'ZAR 176/天（自2025年3月1日起生效）',
