	'te.za.dom.r.6.2': '法定规定',
	'te.za.intl.title': '国际商务出差 — 境外膳宿津贴',
	'te.za.intl.desc': '针对国际商务出差，南非税务局按国家公布以外币计价的每日视同金额（PAYE-GEN-01-G03-A02）。员工前往南非境外出差时，这些金额是餐费及杂费可享受的最高免税标准。\n\n2026税年标准（自2025年3月1日起生效）：\n  • 2026税年的境外标准与2025税年相比未作调整\n  • 请在2026年2月预算演讲后通过sars.gov.za核实2027税年标准\n\n主要规则：\n  • 每个在南非境外的完整日或部分日均适用相应标准\n  • 按津贴支付当日的汇率，将外币视同金额折算为ZAR\n  • 不超过视同标准的金额无需提供收据\n  • 超出部分须通过年度税务评估纳税，而非每月通过PAYE扣缴\n\n国际差旅IRP5代码：\n  • 代码3716：境外膳宿津贴（免税）\n  • 代码3715：境外膳宿津贴（应税超出部分）\n\n南非税务局2026税年部分国家境外膳宿津贴标准：',
	'te.za.intl.source': '南非税务局2026税年境外膳宿津贴表 — 按国家规定以外币计价的每日视同金额（自2025年3月1日起生效）',
