	/* ── Sweden (SE) ── */
	'te.se.dom.title': '国内商务出差 — 每日差旅津贴（Traktamente）',
	'te.se.dom.desc': '瑞典由税务局（Skatteverket）公布法定每日差旅津贴（traktamente）标准。对于需要至少住宿一晚的商务出差，这些标准是雇主可免税报销的最高金额。\n\n2025年国内每日差旅津贴标准（瑞典税务局）：\n  • 全天：SEK 290/天（适用于2025收入年度）\n  • 半天（12:00后出发或19:00前返回）：SEK 145\n  • 私人住宿过夜补贴：SEK 145/晚（无需收据 — 仅适用于行程涵盖午夜至06:00期间）\n\n2026年标准（供参考 — 自2026年1月1日起适用）：\n  • 全天：SEK 300/天\n  • 半天：SEK 150\n  • 私人住宿补贴：SEK 150/晚\n\n长期出差折减：\n  • 在同一地点超过3个月后：按全天标准的70%计算（2025年为SEK 203）\n  • 在同一地点超过2年后：按全天标准的50%计算（2025年为SEK 145）\n\n适用条件：\n  • 出差目的地与员工住所及通常工作地点之间的距离均必须超过50公里\n  • 必须至少住宿一晚\n\n餐费扣减（2025年）— 如雇主提供免费餐食：\n  • 早餐：从每日津贴中扣减SEK 58\n  • 午餐：扣减SEK 102\n  • 晚餐：扣减SEK 102\n\n里程津贴：因公使用私家车可免税报销SEK 2.50/公里。\n注意：住宿费用凭收据按实际金额另行报销。',
	'te.se.dom.source': '瑞典税务局 — 2025年每日差旅津贴：全天SEK 290（自2026年起为SEK 300）；半天SEK 145（自2026年起为SEK 150）',
