	/* ── Switzerland (CH) ── */
	'te.ch.dom.title': '国内商务出差',
	'te.ch.dom.desc': '瑞士没有政府强制规定的每日差旅津贴标准。根据《债务法典》（Obligationenrecht / Code des obligations）第327a条，雇主必须报销员工因履行工作职责而必然发生的所有费用，包括员工在雇主营业场所以外工作时所产生的必要生活费用。\n\n两种报销方式：\n  1. 实报实销（Effektive Spesenverguetung）：凭收据报销实际发生并有文件证明的费用\n  2. 定额津贴（Pauschalspesen）：根据公司获批准的费用规章（Spesenreglement）支付固定金额\n\nESTV（联邦税务管理局）定额费用参考上限（并非法定标准，但被广泛用作税务安全参考标准）：\n  • 午餐/晚餐（无收据）：CHF 30/餐\n  • 午餐/晚餐（有收据）：最高CHF 35/餐（实报实销）\n  • 每日小额费用（杂费）：CHF 20/天\n  • 私家车：CHF 0.70/公里（免税）\n\n经批准的费用规章（Spesenreglement）：\n  • 企业可向相关州税务机关申请批准包含较高定额金额的费用规章\n  • 常见获批准的一次性津贴：员工税后工资的3%–5%，每年最高CHF 24,000\n  • 如无获批准的费用规章，仅ESTV参考上限可视为税务安全标准\n\n所得税：联邦最高税率为11.5%；州税及市镇税的综合负担差异较大：\n  • 楚格州：约16%–18% | 苏黎世州：约24%–26% | 伯尔尼州：约27%–29% | 日内瓦州：约31%–34%\nAHV/AVS社会保障缴费：员工约8.7% + 雇主约8.7%（2025年标准）。',
	'te.ch.dom.source': '无法定每日差旅津贴。联邦税务管理局费用上限：午餐CHF 35（有收据）或CHF 30（定额）；每日小额费用CHF 20/天；里程费CHF 0.70/公里',
	'te.ch.dom.h.0': '类别 / 方法',
