	'te.tz.intl.title': '国际商务出差',
	'te.tz.intl.desc': '国际出差适用相同的《2004年所得税法》框架。真实且有适当文件证明的商务差旅费用报销通常免税。\n\n公务员境外出差的政府参考标准（来源于历史标准，境外差旅标准自约2015年以来未调整）：\n  • 高级官员（主管及以上）：USD 420/天\n  • 中级官员：USD 365/天\n  • 注意：以上为较早期标准 — 请向坦桑尼亚总统办公室公共服务管理部门核实当前标准\n\n美国国务院针对前往坦桑尼亚出差的2025年每日津贴标准：\n  • 达累斯萨拉姆：住宿USD 150/晚 + 餐饮及杂费USD 78/天\n  • 阿鲁沙：住宿USD 130/晚 + 餐饮及杂费USD 71/天\n\n新加坡税务局2025年针对坦桑尼亚的可接受标准：SGD 115/天\n\n私营部门惯例：大多数在坦桑尼亚运营的国际企业会参考美国国务院标准或联合国国际公务员制度委员会每日生活津贴标准制定国际差旅政策。国际差旅预算通常广泛使用USD。',
	'te.tz.intl.source': '政府每日差旅津贴（2022年更新，截至2025年仍适用）：高级官员TZS 250,000/晚；较低级别公务员TZS 100,000/晚',
