	/* ── Thailand (TH) ── */
	'te.th.dom.title': '国内商务出差',
	'te.th.dom.desc': '泰国没有针对私营部门雇主的政府强制性每日差旅津贴标准。企业可自行制定商务差旅政策。\n\n根据《税收法典》第42(1)条的税务处理：\n  • 完全、必要且专门用于履行工作职责的每日差旅津贴（ค่าเบี้ยเลี้ยง）及交通费用，不属于应税收入 — 因此无需缴纳个人所得税（PIT）\n  • 无论金额多少均适用该规定 — 政府未公布上限\n  • 关键条件：相关金额必须本着诚信原则，完全且必要地用于履行工作职责\n  • 如金额明显过高或具有个人用途性质，税务局可能将其视为应税雇佣收入\n\n实务指引：\n  • 凭收据报销实际发生的差旅费用：免税\n  • 合理限额内的固定每日差旅津贴：免税\n  • 过高或无文件证明的固定付款：可能须纳税\n\n政府参考标准（公务员 — 财政部）：\n  • 国内每日差旅津贴按职级划分\n  • 普通员工：THB 240–480/天\n  • 高级官员：THB 480–720/天\n\n2025年个人所得税税率：5%–35%累进税率\n  • 不超过THB 150,000：免税 | THB 150K–300K：5% | THB 300K–500K：10%\n  • THB 500K–750K：15% | THB 750K–1M：20% | THB 1M–2M：25%\n  • THB 2M–5M：30% | 超过THB 5M：35%\n\n最低工资（2024年10月）：THB 363/天（曼谷及主要府）。',
	'te.th.dom.source': '完全且必要地用于履行职责的每日差旅津贴及交通费用不属于应税收入（《税收法典》第42(1)条）',
