	/* ── Turkey (TR) ── */
	'te.tr.dom.title': '国内商务出差 — 国内差旅津贴（Harcırah）',
	'te.tr.dom.desc': '土耳其根据《所得税法》（Gelir Vergisi Kanunu）第24条规定了法定免税每日差旅津贴（harcırah）上限。财政部根据《中央政府预算法》公布的公务员工资系数，每半年更新一次相关上限（1月至6月及7月至12月）。\n\n国内差旅津贴（Harcırah，土耳其境内）— 2025年标准：\n  • 对于每月税前工资不超过TRY 25,467.70的员工：\n    免税上限：TRY 686/天（2025年1月至6月）\n  • 较高工资档次适用按比例提高的免税上限\n  • 来源：《中央政府预算法》附件H（2024年12月31日第32769号《官方公报》）及第323号《所得税法通知》— 2025年第一期\n\n主要规则：\n  • 不超过免税上限的金额：无需缴纳所得税或社会保障缴费\n  • 超过上限的金额：视为应税工资收入 — 须缴纳累进所得税（2025年税率为15%–40%）及社会保障缴费\n  • 标准每半年更新一次 — 请务必通过gib.gov.tr核实当前期间的标准\n\n2025年个人所得税税级（按日历年度累计计算）：\n  • 不超过TRY 158,000：15%\n  • TRY 158,001–330,000：20%\n  • TRY 330,001–800,000：27%\n  • TRY 800,001–4,300,000：35%\n  • 超过TRY 4,300,000：40%\n\n2025年最低工资：每月税前TRY 26,005.50。社会保障（SGK）：雇主按税前工资的20.75%缴纳，员工按14%缴纳（受缴费上限约束）。',
	'te.tr.dom.source': '每半年更新一次：相关系数由财政部制定。2025年1月至6月：TRY 686/天（适用于每月税前工资TRY 25,467.70的工资档次）。每个上半年/下半年均会更新。',
