	/* ── Ukraine (UA) ── */
	'te.ua.dom.title': '国内商务出差 — 每日差旅津贴（Dobovi）',
	'te.ua.dom.desc': '乌克兰根据《税法典》第170.9条规定了法定每日差旅津贴（dobovi）上限。该上限为员工商务出差可享受的最高免税金额。\n\n国内每日差旅津贴（dobovi）— 自2025年1月1日起：\n  • 最高UAH 800/天（免税）\n  • 按每日最低工资的0.1倍计算\n  • 自2025年1月1日起的最低工资：UAH 8,000/月\n  • 因此：0.1 x UAH 8,000 = UAH 800/天\n\n税务处理：\n  • 不超过UAH 800/天：无需缴纳个人所得税（18%）、军事税（5%）或统一社会缴费（USC，雇主22%）\n  • 超过UAH 800/天：超出部分属于应税收入 — 须缴纳18%的个人所得税及5%的军事税，即超出部分的实际综合税率为23%\n\n重要背景 — 戒严状态：\n  • 乌克兰自2022年2月起一直处于戒严状态\n  • 根据第4015-IX号法律，军事税自2024年12月1日起由1.5%提高至5%\n  • 军事税适用于个人的所有应税收入\n  • 超过法定上限的每日差旅津贴须同时缴纳个人所得税（18%）及军事税（5%）\n\n个人所得税税率：雇佣收入统一适用18%。军事税：5%（自2024年12月起）。\n最低工资：UAH 8,000/月（2025年1月）。UAH汇率：USD 1 ≈ UAH 41–42（2025年）。',
	'te.ua.dom.source': 'Forvis Mazars乌克兰：自2025年1月1日起，国内每日差旅津贴为UAH 800/天（最低工资的0.1倍）。国际每日差旅津贴为每个日历日EUR 80（保持不变）。',
