	'te.ua.intl.title': '国际商务出差',
	'te.ua.intl.desc': '针对国际商务出差，乌克兰根据《税法典》第170.9条规定了以欧元计价的固定免税每日差旅津贴上限。\n\n国际每日差旅津贴（dobovi）上限：\n  • 每个日历日最高EUR 80（免税）\n  • 按乌克兰国家银行（NBU）每日公布的官方汇率折算为UAH\n  • 尽管国内标准有所提高，该上限仍保持不变\n\n税务处理：\n  • 不超过EUR 80/天：无需缴纳个人所得税（18%）或军事税（5%）\n  • 超过EUR 80/天：须缴纳18%的个人所得税及5%的军事税\n\n文件要求：\n  • 必须提供出差命令（nakazatel pro komandiruvannya）\n  • 返回后提交费用报告\n  • 提供住宿及交通收据\n\n美国国务院针对前往乌克兰出差的2025年每日津贴标准：\n  • 基辅：住宿USD 150/晚 + 餐饮及杂费USD 78/天\n  • 注意：鉴于出行安全状况，请查阅您所在国家政府发布的旅行建议\n\n新加坡税务局2025年针对乌克兰的可接受标准：SGD 110/天',
	'te.ua.intl.source': '军事税：根据第4015-IX号法律，自2024年12月1日起由1.5%提高至5% — 适用于须缴纳个人所得税的收入，包括超出上限的每日差旅津贴',
	'te.ua.intl.h.0': '目的地 / 类别',
