	/* ── United Arab Emirates (AE) ── */
	'te.ae.dom.title': '国内商务出差 — 阿联酋',
	'te.ae.dom.desc': '阿联酋不征收个人所得税。员工获得的所有报酬，包括工资、奖金、津贴及每日差旅津贴，均完全免税。私营部门雇主也无需遵循任何强制性的每日差旅津贴标准。\n\n法律框架：\n  • 联邦劳动法：2021年第33号法令（《阿联酋劳动法》）\n  • 该法律并未规定私营部门出差必须支付的每日差旅津贴金额\n  • 雇主可自行制定每日差旅津贴及差旅补贴政策\n\nGOSI / 社会保障说明：\n  • 阿联酋国民：适用养老及社会保障总局（GPSSA）缴费 — 雇主12.5% + 员工5% + 政府2.5%\n  • 外籍员工：无需缴纳社会保障费用 — 不享有GPSSA待遇\n  • 每日差旅津贴及差旅补贴通常不计入GPSSA缴费基数\n\n阿联酋企业所得税（CIT）— 自2023年6月起：\n  • 每年超过AED 375,000的应税企业利润适用9%的企业所得税\n  • 该税属于企业税 — 不影响员工的每日差旅津贴或其他津贴\n  • 员工差旅费用报销可作为企业可扣除费用\n\n私营部门常见每日差旅津贴参考标准：\n  • 高级管理人员：国内出差AED 500–1,500/天\n  • 中层管理人员：AED 300–800/天\n  • 普通员工：AED 150–400/天\n\n阿联酋国民最低工资（私营部门，自2026年1月起）：AED 6,000/月。',
	'te.ae.dom.source': '阿联酋不征收个人所得税，也没有强制性的每日差旅津贴标准。所有雇佣报酬，包括津贴及每日差旅津贴，对员工而言均完全免税。',
