	'te.ae.dom.r.7.2': '市场惯例',
	'te.ae.dom.r.8.0': '阿联酋企业所得税（自2023年6月起）',
	'te.ae.dom.r.8.1': '每年超过AED 375,000的企业利润适用9%税率（不适用于员工津贴）',
	'te.ae.dom.r.8.2': '法定规定',
	'te.ae.intl.title': '国际商务出差',
	'te.ae.intl.desc': '对于从阿联酋出发的国际商务出差，同样适用不征收个人所得税的制度。员工获得的所有每日差旅津贴均完全免税。\n\n阿联酋企业通常参考美国国务院或联合国国际公务员制度委员会（UN ICSC）的标准制定国际差旅政策。\n\n美国国务院针对前往阿联酋出差的2025年每日津贴标准：\n  • 迪拜：住宿USD 275/晚 + 餐饮及杂费USD 110/天\n  • 阿布扎比：住宿USD 225/晚 + 餐饮及杂费USD 99/天\n  • 沙迦 / 阿联酋其他地区：住宿USD 185/晚 + 餐饮及杂费USD 86/天\n\n新加坡税务局2025年针对阿联酋的可接受标准：SGD 175/天\n\n阿联酋员工出境出差的常见国际每日差旅津贴：\n  • 美国 / 西欧：USD 280–400/天\n  • 日本 / 新加坡 / 澳大利亚：USD 250–350/天\n  • 亚太地区（不包括日本、新加坡及澳大利亚）：USD 150–250/天\n  • 非洲 / 南亚 / 拉丁美洲：USD 120–200/天\n\n离职金说明：阿联酋离职金（EOSB）仅按基本工资计算 — 每日差旅津贴及其他津贴不会增加离职金负债。',
	'te.ae.intl.source': '阿联酋自2023年6月起实施9%的企业所得税。该税仅适用于企业利润 — 不适用于员工的每日差旅津贴或其他津贴。',
