	/* ── United Kingdom (GB) ── */
	'te.gb.dom.title': '国内商务出差 — HMRC基准定额标准',
	'te.gb.dom.desc': '英国没有法定每日差旅津贴。英国税务海关总署（HMRC）公布基准定额标准，作为建议性的安全港金额。在该标准范围内支付的款项可免税（免征PAYE及国家保险缴费NIC），且无需提供收据。\n\nHMRC国内基准定额标准（2025/26税年 — 与2024/25税年保持不变）：\n  • 离开工作地点超过5小时：GBP 5（餐费津贴）\n  • 离开工作地点超过10小时：GBP 10（餐费津贴）\n  • 离开工作地点超过15小时且行程持续至晚上8点以后：GBP 25\n  • 晚间额外餐费标准（晚上8点后仍在出差）：GBP 10\n  • 过夜杂费：GBP 25/晚\n\n享受免税待遇的条件：\n  1. 出差必须是为了履行工作职责，或前往临时工作地点\n  2. 员工离开正常工作地点的时间必须达到5小时以上或10小时以上\n  3. 员工必须在行程中实际发生餐费\n  4. 每一餐只能报销一次\n\n住宿：\n  • HMRC没有规定住宿基准标准 — 必须按实际发生且有收据证明的费用报销\n  • 或者雇主可向HMRC申请约定的定制标准\n\n里程津贴付款（MAPs — 核准金额）：\n  • 汽车/厢式货车：每个税年的前10,000英里按45便士/英里，之后按25便士/英里\n  • 摩托车：24便士/英里 | 自行车：20便士/英里\n\n超过基准标准支付的金额：除非雇主已通过豁免申请与HMRC约定更高的定制标准，否则超出部分须纳税并缴纳NIC。\n\n所得税（2025/26税年）：个人免税额为GBP 12,570。税率：20%/40%/45%。',
	'te.gb.dom.source': 'HMRC EIM05210/EIM05220：国内基准定额标准；条件包括离开工作地点达到5小时/10小时/15小时；员工必须实际发生餐费；采用定额标准时无需提供收据',
