	'te.gb.dom.r.8.1': '须缴纳PAYE所得税及NIC — 除非已与HMRC约定定制标准',
	'te.gb.dom.r.8.2': '法定规定',
	'te.gb.intl.title': '国际商务出差 — HMRC全球膳宿费标准',
	'te.gb.intl.desc': '针对国际商务出差，HMRC公布按城市划分并每年更新的全球膳宿费标准。员工前往英国境外出差时，按照这些标准支付膳宿费用，可无需提供收据。\n\nHMRC海外标准的结构（按城市）：\n  1. 超过5小时：固定餐费津贴\n  2. 超过10小时：较高的固定餐费津贴\n  3. 24小时标准：涵盖早餐、午餐、晚餐、饮料及酒店至办公地点的交通费用\n  4. 房费标准：每晚住宿费用上限\n\n主要规则：\n  • 员工必须实际发生相关费用\n  • 标准适用于员工在一个工作日内开展大部分业务活动的城市\n  • 超过HMRC海外标准的金额：除非已约定定制标准，否则须纳税并缴纳NIC\n  • 对于未列出的地点：使用HMRC表格中所列的最近城市标准\n\nHMRC部分海外标准（2025/26税年 — 来源于gov.uk）：\n除非另有说明，所有金额均以当地货币计价。完整表格请参阅gov.uk。',
	'te.gb.intl.source': 'HMRC海外定额标准：按城市/国家划分；包括5小时、10小时、24小时及房费标准；每年公布；已针对2025/26税年更新',
