	/* ── United States (US) ── */
	'te.us.dom.title': '国内商务出差 — GSA美国本土每日津贴',
	'te.us.dom.desc': '美国设有完善的每日差旅津贴制度。联邦政府雇员必须采用美国总务管理局（GSA）规定的标准。私营部门雇主可自行设定标准，但采用GSA/美国国税局认可的标准，可使员工自动享受免税待遇。\n\nGSA美国本土每日津贴标准 — 2026财年（2025年10月1日至2026年9月30日生效）：\n  • 美国本土标准住宿费：USD 110/晚\n  • 美国本土标准餐饮及杂费（M&IE）：USD 68/天\n  • 标准总额：USD 178/天（与2025财年保持不变 — GSA公告FTR 26-01）\n\n非标准地区（NSA）说明：\n  • 约300个高成本地区适用更高标准（例如曼哈顿住宿费为USD 342）\n  • 非标准地区的餐饮及杂费：根据地点不同为USD 68–92/天\n  • 出差首日及最后一日：按餐饮及杂费标准的75%计算\n\n美国国税局针对私营部门的税务处理（可核算计划）：\n  • 在可核算计划下，按照不超过GSA标准支付的每日差旅津贴：不属于员工应税收入 — 无需缴纳所得税或《联邦保险缴款法案》税款（FICA）\n  • 可核算计划要求：具备业务目的、提供费用证明，并在合理期限内退还多余预付款\n  • 超过GSA标准的每日差旅津贴：超出部分属于应税薪酬 — 须缴纳联邦所得税及FICA税款\n\n美国国税局高低成本每日津贴法（私营部门替代方法）：\n  • 2026财年（2025年10月1日至2026年9月30日）：\n    高成本地区：USD 319/天（住宿USD 233 + 餐饮及杂费USD 86）\n    低成本地区：USD 225/天（住宿USD 151 + 餐饮及杂费USD 74）\n\n里程报销：美国国税局标准费率为每英里67美分（2024年 — 请核实2025/2026年更新）。',
	'te.us.dom.source': 'GSA 2026财年美国本土标准：USD 178/天（住宿USD 110 + 餐饮及杂费USD 68）。标准与2025财年保持不变（GSA公告FTR 26-01）。',
