	'te.us.intl.title': '国际商务出差 — 美国国务院海外每日津贴标准',
	'te.us.intl.desc': '针对国际商务出差，美国国务院会在aoprals.state.gov每月更新并公布海外地区（OCONUS，美国本土以外地区）每日津贴标准。该标准涵盖150多个国家及数千个城市，包括住宿费及餐饮和杂费金额。\n\n结构：住宿费（按实际费用报销，但不超过上限）+ 餐饮及杂费（固定每日津贴）\n\n美国国税局针对私营部门的税务处理：\n  • 在可核算计划下，按照不超过美国国务院标准支付的每日差旅津贴：免税\n  • 超过美国国务院标准的金额：属于应税薪酬\n\n美国国务院部分每日津贴标准 — 2025/2026财年（现行）：\n（注意：美国国务院标准每月更新 — 请通过aoprals.state.gov核实）',
	'te.us.intl.source': '美国国税局：私营部门可核算计划规则 — 对员工而言，按照不超过GSA/美国国务院标准支付的每日差旅津贴免税（美国国税局第463号刊物）',
