	'te.uz.intl.title': '国际商务出差',
	'te.uz.intl.desc': '国际商务出差适用相同的乌兹别克斯坦《税法典》框架。法定标准范围内的每日差旅津贴免税。\n\n国际每日差旅津贴法定标准：\n  • 通常以美元等值金额或基础计算值（BCV）的倍数表示\n  • 企业通常参考公务员境外出差的政府标准，或采用美国国务院标准作为参考\n\n美国国务院针对前往乌兹别克斯坦出差的2025年每日津贴标准：\n  • 塔什干：住宿USD 135/晚 + 餐饮及杂费USD 60/天\n\n新加坡税务局2025年针对乌兹别克斯坦的可接受标准：SGD 85/天\n\n乌兹别克斯坦员工出境出差的私营部门参考标准：\n  • 美国 / 西欧：USD 250–380/天\n  • 俄罗斯 / 独联体国家：USD 80–180/天\n  • 中国 / 东亚：USD 150–250/天\n  • 中东 / 海湾地区：USD 150–250/天\n\n注意：乌兹别克斯坦经济近年来快速增长（年增长率约5%–6%）。自2023年以来，税率及社会缴费比例已进行改革。请始终通过soliq.uz核实当前基础计算值及法定标准。',
	'te.uz.intl.source': '国际出差：适用相同的《税法典》框架 — 法定标准范围内的每日差旅津贴免税。超出标准的金额须缴纳12%的个人所得税。',
