	'te.vn.dom.r.6.0': '2025年个人所得税法改革',
	'te.vn.dom.r.6.1': '个人扣除额提高至每月VND 15.5M；税级由7级减少至5级（请通过gdt.gov.vn核实生效日期）',
	'te.vn.dom.r.6.2': '法定规定',
	'te.vn.intl.title': '国际商务出差',
	'te.vn.intl.desc': '国际商务出差适用相同的个人所得税法律框架。完全且必要地用于履行工作职责的每日差旅津贴不属于应税收入。\n\n政府并未针对私营部门公布统一的国际差旅津贴标准表。\n\n美国国务院针对前往越南出差的2025年每日津贴标准：\n  • 河内：住宿USD 153/晚 + 餐饮及杂费USD 81/天\n  • 胡志明市：住宿USD 168/晚 + 餐饮及杂费USD 84/天\n\n新加坡税务局2025年针对越南的可接受标准：SGD 70/天\n\n越南员工出境出差的私营部门参考标准：\n  • 美国 / 西欧：USD 250–380/天\n  • 日本 / 韩国 / 新加坡 / 澳大利亚：USD 200–300/天\n  • 亚洲区域内（中国、东盟）：USD 120–200/天\n\n社会保险：员工向社会保险基金缴纳8%（缴费基数上限为基本工资的20倍，即VND 46,800,000）。雇主社会保险总缴费比例约为17.5%。差旅津贴不计入社会保险缴费基数。',
	'te.vn.intl.source': '越南2025年个人所得税法修正案：个人扣除额由每月VND 11M提高至VND 15.5M；税级由7级减少至5级（生效日期尚待确认）',
